	base = safeRepoPathComponent(base)
	if base == "" || base == "." || base == string(filepath.Separator) {
		base = "repo"
	}
	sum := sha256.Sum256([]byte(repoDir))
	return base + "-" + hex.EncodeToString(sum[:])[:12]
