// releaseFunc closes the descriptor as well as unlocking: the flock is held per
// OPEN FILE DESCRIPTION, so a leaked descriptor keeps the lock alive.
func releaseFunc(f *os.File) func() {
	return func() {
		_ = unlockFile(f)
		_ = f.Close()
	}
