// lockFileName is the advisory lockfile under the bare git dir that serializes
// Advance across processes. It is not a git object/ref, so go-git ignores it.
const lockFileName = "factgitmeta.lock"

// localRepo is a bare, on-disk go-git repository used as the local git-meta
// object + ref store. Its *filesystem.Storage implements BOTH
// storer.EncodedObjectStorer (the git-meta Serialize/BuildCommit target) and
// storer.ReferenceStorer (ref compare-and-swap via CheckAndSetReference), so the
// whole read-merge-CAS loop runs against a plain directory with no network,
// entiredb, or Postgres. This is the deliberate local substitute for
// git-meta-service's gitclient (memory.Storage + smart-HTTP push): same engine,
// no transport.
type localRepo struct {
	store  *filesystem.Storage
	gitDir string // absolute path to the bare repo; backs the advisory lockfile
}

// openLocalRepo opens the bare repository at gitDir, laying down the standard
// git layout (objects/, refs/, HEAD, config) on first use. A missing directory
// is created. Re-opening an already-initialized dir is not an error; that is
// the steady state after the first sync.
func openLocalRepo(gitDir string) (*localRepo, error) {
	if gitDir == "" {
		return nil, errors.New("factgitmeta: git dir is empty")
	}
	if err := os.MkdirAll(gitDir, 0o700); err != nil {
		return nil, fmt.Errorf("factgitmeta: create git dir %q: %w", gitDir, err)
	}
	// A nil cache is valid (see git-meta-service client_test) but re-reads every
	// object from disk; a small LRU keeps the tree/commit reads in the CAS loop
	// cheap.
	store := filesystem.NewStorage(osfs.New(gitDir), cache.NewObjectLRUDefault())
	// Init writes HEAD/config and the refs/objects dirs. ErrTargetDirNotEmpty
	// means the repo is already initialized (a re-open), which is expected and
	// not an error; any other failure is real.
	if _, err := git.Init(store); err != nil && !errors.Is(err, git.ErrTargetDirNotEmpty) {
		return nil, fmt.Errorf("factgitmeta: init bare repo %q: %w", gitDir, err)
	}
	return &localRepo{store: store, gitDir: gitDir}, nil
}

// lock takes a cross-process exclusive advisory lock on a lockfile in the
// git dir and returns an unlock func the caller must defer. It serializes the
// whole Advance read-CAS loop across processes: go-git performs the create-path
// ref write (CheckAndSetReference with a nil old ref) UNCONDITIONALLY (it skips
// the absence check when old==nil), so without this, two concurrent first-syncs
// would both "win" and silently drop one member's facts. The update path is
// already ref-CAS-safe under go-git's own flock; this also closes its benign
// read→write TOCTOU. The OS lock is released automatically if the process dies,
// so a crash never leaves a stale lock.
func (r *localRepo) lock() (func(), error) {
	f, err := r.openLockFile()
	if err != nil {
		return nil, err
	}
	if err := lockFile(f); err != nil {
		_ = f.Close()
		return nil, fmt.Errorf("factgitmeta: acquire lock: %w", err)
	}
	return releaseFunc(f), nil
}

// tryLock is lock() without the wait: ok=false means another writer holds the
// lock right now. A best-effort background pass (the entity index's freshness
// tick) uses it so contention costs a skipped pass instead of an unbounded,
// context-deaf block inside flock(2) — a Go context cannot interrupt that
// syscall, so a blocking acquire would outlive the caller's own deadline.
func (r *localRepo) tryLock() (func(), bool, error) {
	f, err := r.openLockFile()
	if err != nil {
		return nil, false, err
	}
	locked, err := tryLockFile(f)
	if err != nil {
		_ = f.Close()
		return nil, false, fmt.Errorf("factgitmeta: acquire lock: %w", err)
	}
	if !locked {
		_ = f.Close()
		return nil, false, nil
	}
	return releaseFunc(f), true, nil
}

func (r *localRepo) openLockFile() (*os.File, error) {
	f, err := os.OpenFile(filepath.Join(r.gitDir, lockFileName), os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("factgitmeta: open lockfile: %w", err)
	}
	return f, nil
}

// releaseFunc closes the descriptor as well as unlocking: the flock is held per
// OPEN FILE DESCRIPTION, so a leaked descriptor keeps the lock alive.
func releaseFunc(f *os.File) func() {
	return func() {
		_ = unlockFile(f)
		_ = f.Close()
	}
}
// repoFilterDriverOverrides returns the config overrides that disarm every
// filter driver the REPOSITORY configures. The common case -- no repo-local
// filter driver at all -- returns nil and costs nothing beyond the probe.
//
// The result is cached per repository, keyed by a stat signature of the config
// files it can come from, so a config that changes underneath us is picked up
// while a steady repository costs one `git config` for the whole process. That
// matters: history indexing runs thousands of git commands, and a fork per
// command would be a visible slowdown.
func repoFilterDriverOverrides(ctx context.Context, repoDir string) ([]gitConfigOverride, error) {
	if strings.TrimSpace(repoDir) == "" {
		return nil, nil
	}
	signature := repoConfigSignature(repoDir)
	cached, ok := repoFilterCache.Load(repoDir)
	if ok {
		if entry := cached.(*repoFilterCacheEntry); entry.signature == signature {
			return entry.overrides, nil
		}
	}
	overrides, err := enumerateRepoFilterDrivers(ctx, repoDir)
	if err != nil {
		if ok {
			repoFilterCache.CompareAndDelete(repoDir, cached)
		}
		return nil, err
	}
	repoFilterCache.Store(repoDir, &repoFilterCacheEntry{signature: signature, overrides: overrides})
	return overrides, nil
}

// enumerateRepoFilterDrivers asks git which filter.* keys the repository itself
// sets. It spawns git directly rather than going through the hardened runner:
// the runner calls back into this function, and `git config` reads no worktree
// content, so no filter can run during the probe.
//
// Spawning directly means hardenedGitArgs does not run here, so this is the one
// git invocation in the binary that has to carry gitHardenConfig itself.
// Splicing the shared slice in rather than repeating its flags is what keeps
// the probe from drifting behind the chokepoint: core.hooksPath was added to
// gitHardenConfig after a `.git/hooks/post-index-change` was found to execute
// during indexing, and a hand-copied `-c core.fsmonitor=false` here would have
// silently missed it. `git config` does not touch the index and so cannot fire
// post-index-change today; the flags are applied because "every git spawn is
// hardened" is a cheaper invariant to keep than a per-call-site argument about
// which hooks a subcommand can reach.
func enumerateRepoFilterDrivers(ctx context.Context, repoDir string) ([]gitConfigOverride, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	runCtx, cancel := context.WithTimeout(ctx, repoFilterEnumerateTimeout)
	defer cancel()
	// -z keeps the output unambiguous for a subsection name containing a
	// newline; --show-scope tells local/worktree apart from global/system.
	args := append(slices.Clone(gitHardenConfig),
		"config", "-z", "--show-scope", "--name-only", "--get-regexp", `^filter\..*\.(clean|smudge|process|required)$`)
	cmd := exec.CommandContext(runCtx, "git", args...)
	cmd.Dir = repoDir
	out, err := cmd.Output()
	if err != nil {
		if runCtx.Err() != nil {
			return nil, fmt.Errorf("enumerate repository filter drivers: %w", runCtx.Err())
		}
		// Git reports no matching keys with exit 1 and no output. Any other
		// failure must block the protected command and must not enter the cache.
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 && len(out) == 0 && len(exitErr.Stderr) == 0 {
			return nil, nil
		}
		return nil, fmt.Errorf("enumerate repository filter drivers: %w", err)
	}
	fields := strings.Split(string(out), "\x00")
	seen := map[string]bool{}
	var drivers []string
	for i := 0; i+1 < len(fields); i += 2 {
		scope, key := fields[i], fields[i+1]
		if scope != "local" && scope != "worktree" {
			continue
		}
		driver, ok := filterDriverFromConfigKey(key)
		if !ok || seen[driver] {
			continue
		}
		seen[driver] = true
		drivers = append(drivers, driver)
	}
	var overrides []gitConfigOverride
	for _, driver := range drivers {
		for _, k := range gitFilterOverrideKeys {
			overrides = append(overrides, gitConfigOverride{Key: "filter." + driver + "." + k.suffix, Value: k.value})
		}
	}
	return overrides, nil
}

// filterDriverFromConfigKey pulls "na=me" out of "filter.na=me.clean". The
// driver name is everything between the first and last dot, so a name
// containing dots, equals signs or spaces round-trips intact.
func filterDriverFromConfigKey(key string) (string, bool) {
	rest, ok := strings.CutPrefix(key, "filter.")
	if !ok {
		return "", false
	}
	dot := strings.LastIndex(rest, ".")
	if dot <= 0 {
		return "", false
	}
	return rest[:dot], true
}

// repoConfigSignature is a cheap fingerprint of the config files a repository
// can carry its own filter drivers in. An empty signature (a repoDir that is
// not a repository root, so the files cannot be located) still caches, which is
// safe: a repository does not rewrite its own config mid-run without already
// having execution.
func repoConfigSignature(repoDir string) string {
	gitDir := filepath.Join(repoDir, ".git")
	if info, err := os.Stat(gitDir); err == nil && !info.IsDir() {
