type recordingRunner struct{ calls [][]string }

func (r *recordingRunner) Run(_ context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
	r.calls = append(r.calls, append([]string{dir, name}, args...))
	return nil, nil, nil
}

