func TestIsGitCheckout(t *testing.T) {
	dir := t.TempDir()
	if isGitCheckout(dir) {
		t.Errorf("a bare temp dir is not a checkout")
	}
	if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	if !isGitCheckout(dir) {
		t.Errorf("a dir with a .git directory is a checkout")
	}
}
