// daemonWatchOptions is the EFFECTIVE configuration one workspace's pass runs
// with under the installed daemon, so the semantics tests are driven by what the
// daemon really does rather than by a hand-built option struct that could drift.
//
// It is two halves because the daemon is: the installed argv is constant and
// workspace-independent (that is what stops a second repo's `setup` overwriting
// the first repo's unit), and everything per-workspace comes from the machine
// watch plan the running daemon re-reads. A test that read only one half would
// pass while the other silently lost the user's cap, agent or model.
func daemonWatchOptions(t *testing.T, setupOpts setupCommandOptions) watchCommandOptions {
	t.Helper()
	w := defaultWatchOptions()
	cmd := &cobra.Command{Use: "watch", RunE: func(*cobra.Command, []string) error { return nil }}
	bindWatchFlags(cmd, &w)
	args := brainWatchDaemonArgs(setupOpts)
	// Drop the "workspace watch" verb prefix; the daemon passes no positional
	// workspace, because it watches every workspace in the plan.
	if err := cmd.ParseFlags(args[2:]); err != nil {
		t.Fatalf("parse daemon argv %v: %v", args, err)
	}
	return applyWatchPlanEntry(w, setupWatchPlanEntryFor(setupOpts, setupTestNow))
}

// TestDaemonBudgetSemanticsAllowOneRunPerWindow is the regression test for the
// one-shot daemon. The installed watcher is a KeepAlive service that never
// exits, and --budget counts gated agent runs for the life of the PROCESS with
// no reset — so `--budget 1` did not mean "one run per --distill-every window",
// it meant one run EVER, machine-wide, across every repo. A machine that
// distilled once and then never again looked healthy in every status output.
//
// This simulates the real daemon: one long-lived process, one shared agentCalls
// counter (workspaceWatchLoop's), two member repos with their own cursors,
// across three --distill-every windows. The contract is one gated run per repo
			//	operation must be run in a work tree
			//
			// The same repository WITHOUT --worktree already said "bare
			// repository has no working tree ... point it at a clone with a
			// checkout". Same condition, same sentence.
			return nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("fingerprint worktree for seed: %w", err))
		}
	}

	scan, err := scanSeedRepository(ctx, opts.Runner, repoDir, storage.Key, seedOpts)
	if err != nil {
		return err
	}
	scan.Coverage = buildSeedHistoryCoverage(ctx, opts.Runner, repoDir, outputDir)
	if scan.Coverage != nil && scan.Coverage.MissingSessionCommits > 0 {
		scan.Warnings = append(scan.Warnings, fmt.Sprintf("%d commits after oldest session have no Entire checkpoint trailer; see seed/history-gaps.md", scan.Coverage.MissingSessionCommits))
	}
	// The manifest gets a bounded projection of the coverage record; the full
	// per-commit list stays in seed/history-gaps.md, which is where it is meant
	// to be read. See manifestSeedHistoryCoverage.
	manifestCoverage := manifestSeedHistoryCoverage(scan.Coverage)
	if manifestCoverage != nil && manifestCoverage.UncoveredCommitsTruncated {
