func splitNonEmptyLines(data []byte) []string {
	var lines []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(filepath.ToSlash(line))
		if line != "" {
			lines = append(lines, line)
		}
	}
