package agentsetup

import (
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

func fixtureOptions(t *testing.T, plugins ...string) Options {
	t.Helper()
	return Options{StateDir: t.TempDir(), ConfigDir: t.TempDir(), DataDir: t.TempDir(), ListPlugins: func() (string, error) {
		if len(plugins) == 0 {
			return "No plugins installed in /fixture.\nInstall one with 'entire plugin install <name|url|path>', or drop an entire-<name> binary anywhere on $PATH.\n", nil
		}
		text := "Managed plugin directory: /fixture\n\n"
		for _, plugin := range plugins {
			text += "  " + plugin + " v1.0.0 → /fixture/entire-" + plugin + "\n"
		}
		return text, nil
	}}
}
func fixtureSetup(t *testing.T, repo string, opts Options, content string) string {
	t.Helper()
	canonical, err := filepath.EvalSymlinks(repo)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(opts.StateDir, "repos", filepath.FromSlash(localKey(canonical)), "setup.json")
	mkdirAllForTest(t, filepath.Dir(path))
	writeFileForTest(t, path, content)
	return path
}
func TestCoordinationModes(t *testing.T) {
	for _, product := range []string{"graph", "brain"} {
		for _, previous := range []string{"", GraphGuide, BrainGuide(), CombinedGuide} {
			for _, configured := range []bool{false, true} {
				t.Run(product+"/"+strings.Split(previous, "\n")[0]+"/configured="+strconv.FormatBool(configured), func(t *testing.T) {
					repo := t.TempDir()
					opts := fixtureOptions(t, "graph", "brain")
					opts.ListPlugins = func() (string, error) { t.Fatal("queried global plugin inventory"); return "", nil }
					if configured {
						fixtureSetup(t, repo, opts, `{"schema_version":1}`)
package agentsetup

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Existing names remain redirects for clients with explicit legacy imports.
// There is exactly one workflow body, in Path; generated files are not setup state.
const legacyRedirect = "Read the repository-root .entire/agent-guide.md for the current agent workflow.\n"

func migrateMarkers(content []byte) ([]byte, error) {
	for _, product := range []string{"graph", "brain"} {
		begin, end := []byte("<!-- entire-"+product+":begin -->"), []byte("<!-- entire-"+product+":end -->")
		n, m := bytes.Count(content, begin), bytes.Count(content, end)
		if n == 0 && m == 0 {
			continue
		}
		a, b := bytes.Index(content, begin), bytes.Index(content, end)
		if n != 1 || m != 1 || a >= b {
			return nil, fmt.Errorf("malformed Entire %s managed markers; repair before regenerating", product)
		}
		})
	}
}

func TestGitFilterProbeFailureEvictsPreviousSuccess(t *testing.T) {
	gitHardenSkipUnsupported(t)
	repo, _ := gitHardenFilterRepo(t, "probe", "clean")
	t.Cleanup(func() { repoFilterCache.Delete(repo) })
	if _, err := repoFilterDriverOverrides(context.Background(), repo); err != nil {
		t.Fatal(err)
	}
	config := filepath.Join(repo, ".git", "config")
	original, err := os.ReadFile(config)
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(config)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(config, append(original, []byte("\n[invalid\n")...), 0600); err != nil {
		t.Fatal(err)
	}
	if _, err := repoFilterDriverOverrides(context.Background(), repo); err == nil {
		t.Fatal("invalid config probe should fail")
	}
	if _, cached := repoFilterCache.Load(repo); cached {
		t.Error("failed probe retained the previous successful cache entry")
	}
	if err := os.WriteFile(config, original, 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.Chtimes(config, info.ModTime(), info.ModTime()); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := repoFilterDriverOverrides(ctx, repo); err == nil {
		t.Fatal("restored stat signature reused stale cache instead of probing")
	}
	if overrides, err := repoFilterDriverOverrides(context.Background(), repo); err != nil || len(overrides) == 0 {
		t.Fatalf("healthy retry: overrides=%v err=%v", overrides, err)
	}
}

