import("os";"path/filepath";"testing";"time")
func TestAuditGenerationPermissionLoop(t *testing.T) {
 root:=t.TempDir()
 if err:=os.Chmod(root,0200);err!=nil {t.Fatal(err)}
 defer os.Chmod(root,0700)
 if _,err:=os.Lstat(filepath.Join(root,"id")); !os.IsPermission(err) { t.Skipf("requires non-root permission enforcement: %v",err) }
 done:=make(chan string,1)
 go func(){done<-semanticAvailableGenerationID(root,"id","suffix")}()
 select {case got:=<-done: t.Logf("returned %s",got)
