// errDistillPassBusy reports that the gated distill did NOTHING because another
// process already held the brain's distill pass lock. `distill` itself treats
// that as success — someone else is doing the work — but the watcher must not:
// it had already reserved the --distill-every window, so a silent success burned
// a whole window (24h by default) on a no-op and logged "spent tokens". `setup`
// creates that collision by design, spawning an hours-long detached backfill and
// installing a watcher that ticks immediately after.
var errDistillPassBusy = errors.New("another distill pass holds this brain")

func watchDistill(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, repoDir string) error {
	distillOpts := watchDistillOptions(w)
	busy := false
	distillOpts.onPassSkipped = func() { busy = true }
	sub := &cobra.Command{}
	sub.SetContext(ctx)
	sub.SetOut(cmd.OutOrStdout())
	sub.SetErr(cmd.ErrOrStderr())
	if err := runDistill(ctx, sub, opts, distillOpts, repoDir); err != nil {
		return err
	}
	if busy {
		return errDistillPassBusy
	}
	return nil
}

func watchDistillOptions(w watchCommandOptions) distillCommandOptions {
	jobs := w.distillJobs
	if jobs <= 0 {
		jobs = 1
	}
	// A negative cap is a typo, not "unlimited". Only an explicit 0 means that.
	maxSessions := w.distillMaxSessions
	if maxSessions < 0 {
		maxSessions = 0
	}
	return distillCommandOptions{
		agent:               w.distillAgent,
		model:               w.model,
		effort:              w.effort,
		timeout:             defaultDistillTimeout,
		maxChunkBytes:       defaultDistillChunkSize,
		confidenceThreshold: defaultFactConfidenceThreshold,
		// The per-pass VOLUME cap. A capped pass is ordered newest-first,
		// matching what `setup` says it did and what a reader wants first; the
		// deferred remainder stays UNCACHED, so the next window picks it up
		// rather than it being skipped forever. Ordering is left alone when
		// there is no cap, so an uncapped `watch --distill` is unchanged.
		maxSessions: maxSessions,
		newestFirst: maxSessions > 0,
		jobs:        jobs,
		// concurrency is what the distill pipeline (and runDistill's guard)
		// actually reads; --jobs is only its compatibility alias. Leaving it at
		// the zero value made every gated distill the watcher ever attempted
		// fail with "--concurrency must be greater than 0" before making a
		// single agent call.
		concurrency: jobs,
	}
}

func loadWatchCursor(path string) watchCursor {
	var c watchCursor
	data, err := os.ReadFile(path)
	if err != nil {
		return c
	}
	_ = json.Unmarshal(data, &c)
	// unlimited). Paired with newestFirst it is "distill the N newest sessions
	// that still need it", the token budget for a backfill pass; the remaining
	// sessions stay uncached and are picked up by the next run or the watcher.
	maxSessions int
	// concurrency is the distill agent-call pool size; <=1 means strictly
	// sequential, lazy agent calls (the zero value keeps tests and library
	// callers on the old behavior). See chunkPrefetcher for the pool semantics.
	concurrency int
	// flushEvery overrides distillFlushCallInterval when >0 (tests use 1 to
	// observe mid-run persistence).
	flushEvery int
	run        distillAgentRunner
	// progress, when set, is called as each session is processed so the command
	// can render a spinner/progress line. It is nil in tests and for callers
	// that do not want progress output.
	progress func(distillProgress)
	// entityProvenance, when set, sharpens each new fact's anchor from the
	// entity -> checkpoint index: the checkpoint that actually changed the
	// entity the fact's locus names, instead of the session's LAST checkpoint.
	// nil (the zero value, and the value in every pre-index caller) keeps the
	// original coarse anchoring exactly.
	entityProvenance *entityProvenanceResolver
}

// distillProgress reports how far the distillation loop has advanced. Distill
// runs one agent call per transcript chunk and can take minutes, so this drives
// a refresh-style progress line.
type distillProgress struct {
	SessionsDone  int
	SessionsTotal int
	Branch        string
	Facts         int // candidate facts the agent has produced so far
}

// transcriptChunk is a line-numbered slice of one session transcript handed to
// the agent. StartLine is the 1-based line offset of the chunk's first line in
// the original transcript, used as the chunk's provenance anchor in Phase A.
type transcriptChunk struct {
	StartLine int
	EndLine   int
	Text      string
}

// distillCache memoizes the fingerprint of each session that has been
// distilled, so an incremental run skips sessions whose transcript and
// checkpoint are unchanged.
type distillCache struct {
	Version  int               `json:"version"`
	Sessions map[string]string `json:"sessions"`
}

type distillPlan struct {
	Sessions           []distillSessionPlan
	Work               []distillChunkWork
