	"os"
	"path/filepath"
	"testing"
)

func TestCorruptSnapshotIsNotCurrent(t *testing.T) {
	root := t.TempDir()
	rel := "semantic/snapshots/current/snapshot.ndjson"
	if err := os.MkdirAll(filepath.Dir(filepath.Join(root, rel)), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, rel), []byte("not a semantic snapshot"), 0600); err != nil {
		t.Fatal(err)
	}
	source := &semanticSourceManifest{Commit: "head", Tree: "tree", SnapshotPath: rel, WorktreeMode: "head"}
	reason, ok := semanticIndexAlreadyCurrent(root, source, semanticIndexOptions{}, "head", "tree", "")
	if ok {
		t.Errorf("corrupt snapshot accepted as current: %s", reason)
	}
}

