func runRefresh(ctx context.Context, cmd *cobra.Command, opts Options, refreshOpts refreshCommandOptions) error {
	if refreshOpts.allBranches && !refreshOpts.semantic {
		return errors.New("--all-branches requires --semantic")
	}
	outputExplicit := cmd.Flags().Changed("output")
	if outputExplicit && strings.TrimSpace(refreshOpts.outputDir) == "" {
		return errors.New("--output must not be empty")
	}
	repoDir, err := exportRepoDir(opts.Env)
	if err != nil {
		return err
	}
	if refreshOpts.force {
		refreshOpts.seed.force = true
	}
	if outputExplicit {
		if refreshOpts.force {
			if err := removeForcedOutputDir(refreshOpts.outputDir, repoDir); err != nil {
				return err
			}
		} else if _, err := validateExportDirAvailable(refreshOpts.outputDir); err != nil {
			return err
		}
	}
	if refreshOpts.seed.agent == "auto" {
		refreshOpts.seed.agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
	}
	progress := newRefreshProgress(cmd.ErrOrStderr())
	// stage reports one stage's outcome and answers "must this abort the
	// refresh?". Outside best-effort mode the answer is the old one — any error
	// aborts. Inside it, nothing does: the caller collects the per-component
	// outcomes and decides.
	stage := func(name string, err error) bool {
		if refreshOpts.component != nil {
			refreshOpts.component(name, err)
			return false
		}
		return err != nil
	}
	storageTask := progress.Begin("locate brain")
	storage, storageErr := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if storageErr != nil {
		storageTask.Finish(storageErr)
		return storageErr
	}
	storageTask.Update("locate brain: " + storage.Key)
	storageTask.Finish(nil)
	brainDir := storage.BrainDir
	if outputExplicit {
		finishOutput := progress.Step("resolve output path")
		brainDir, err = filepath.Abs(refreshOpts.outputDir)
		if err != nil {
			finishOutput(err)
			return fmt.Errorf("resolve output directory: %w", err)
		}
		finishOutput(nil)
	}
	// Before any stage writes, not after: a manifest carrying another build's
	// fields is readable but no writer will replace it, and the session export
	// below is a writer. Discarding it afterwards let the export fail first, and
	// refresh then reported "unavailable, using seed baseline" -- masking the
	// real cause and throwing away the sessions it had just gathered. An
	// explicit --force is the operator asking for the rebuild, so clear the way
	// for it here. An explicit --output has already had its directory removed.
	if refreshOpts.force && !outputExplicit {
		discarded, derr := discardManifestThisBuildCannotRewrite(brainDir)
		if derr != nil {
			return derr
		}
		if discarded {
			fmt.Fprintln(cmd.ErrOrStderr(), "refresh: discarded a manifest written by a different build; rebuilding it")
		}
	}
	exportCmd := &cobra.Command{Use: "export"}
	exportCmd.SetOut(io.Discard)
	exportCmd.SetErr(io.Discard)
	exportOpts := exportCommandOptions{
		outputDir:       defaultExportDir,
		outputExplicit:  outputExplicit,
		checkpointLimit: refreshOpts.checkpointLimit,
		entireBinary:    refreshOpts.entireBinary,
		rawTranscript:   refreshOpts.rawTranscript,
		scope:           refreshOpts.scope,
	}
	if outputExplicit {
		exportOpts.outputDir = refreshOpts.outputDir
	}
	var exportErr error
	finishExportTask := func(error) {}
	updateExportTask := func(string) {}
	if !refreshOpts.skipSessions {
		exportTask := progress.Begin("export sessions")
		exportOpts.progress = func(p exportProgress) {
			// The bar is fed from the SAME numbers the label prints, so the two
			// can never disagree; refreshExportProgressCounts picks whichever
			// pair the exporter is currently counting (items, else checkpoints).
			done, total := refreshExportProgressCounts(p)
			exportTask.SetProgress(done, total)
			exportTask.Update(refreshExportProgressLabel(p))
		}
		exportErr = runExport(ctx, exportCmd, opts, exportOpts)
		exportTaskFinished := false
		finishExportTask = func(err error) {
			if exportTaskFinished {
				return
			}
			exportTask.Finish(err)
			exportTaskFinished = true
		}
		updateExportTask = exportTask.Update
		if exportErr == nil {
			finishExportTask(nil)
		}
	} else {
		progress.Skip("export sessions")
	}

	manifest, _ := loadBrainManifest(brainDir)
	needSeed := outputExplicit || refreshOpts.seed.force
	// seedProbeErr is a freshness check that could not RUN — `git rev-parse
	// HEAD` failing on an unborn branch, an interrupted git state, or git
	// missing from a daemon's PATH. Returning it raw punched a hole straight
	// through the never-abort contract this best-effort mode exists to keep
	// (setup.go's instant phase): the phase died before reporting a single
	// component, so instant.json was never written, `status` and `doctor` could
	// not name the reason, and the workspace, the daemon and the backfill were
	// all skipped. It is a failed SEED source, so it is reported as one.
	var seedProbeErr error
	if !needSeed {
		needSeed, seedProbeErr = seedRefreshNeeded(ctx, opts, repoDir, manifest, refreshOpts.seed.worktree)
		if seedProbeErr != nil {
			// Freshness unknown: leave the existing seed alone rather than
			// rebuilding one on the strength of a check that did not run.
			needSeed = false
		}
	}
	if exportErr != nil && (manifest == nil || manifest.Sources == nil) && seedProbeErr == nil {
		needSeed = true
	}
	// hostCLIAbsent is the ONE export failure that is not this brain's fault:
	// the Entire CLI session capture reads through is not installed. It is an
	// environmental fact, identical on the first refresh and the hundredth, and
	// no repair applies to it — so it degrades unconditionally, with the cause
	// named and the install step attached (see host_cli.go).
	//
	// It is deliberately NOT folded into the clause above. That clause asks
	// "does this brain have a baseline at all", which is genuinely a first-run
	// question, and it is why a missing `entire` degraded on run 1: a fresh
	// store has no manifest, so the seed fallback caught the failure on its way
	// past. Run 2 has a manifest, the clause is false, and the SAME condition
	// became a fatal raw `exec: "entire": executable file not found in $PATH`
	// — while `status` went on recommending the command that produced it.
	//
	// Keeping the two separate is also what preserves what the manifest test
	// was protecting. An export that RAN and failed still aborts here, because
	// answering real loss with "unavailable, using seed baseline" is the
	// masking this file already had to undo once (see
	// discardManifestThisBuildCannotRewrite above); only the launch failure is
	// forgiven, and only because there is nothing to fix in the brain.
	hostCLIAbsent := hostCLIMissing(exportErr, refreshOpts.entireBinary)
	if hostCLIAbsent {
		exportErr = hostCLIMissingExportError(exportErr, refreshOpts.entireBinary)
	}
	// The sessions component is reported exactly once, here, where the export
	// outcome and the seed fallback are both known: a failed export that a seed
	// baseline papers over is still a failed sessions source, and saying so is
	// the whole point of a per-component report.
	var degradedSessions error
	if !refreshOpts.skipSessions {
		if exportErr != nil && !needSeed && !hostCLIAbsent {
			finishExportTask(exportErr)
			if stage(brainComponentSessions, exportErr) {
				return exportErr
			}
		} else if stage(brainComponentSessions, exportErr) {
			degradedSessions = exportErr
		}
	}
		return false
	}
	history := manifest.Sources.History
	if history.IndexPath == "" || history.SessionsFingerprint == "" || history.IndexBytes <= 0 ||
		!validHistorySHA256(history.IndexSHA256) || !validHistorySHA256(history.RecordsFingerprint) ||
		!validHistorySHA256(history.TranscriptsFingerprint) {
		return false
	}
	if history.SessionsFingerprint != sessionSourceFingerprint(manifest.Sources.Sessions) {
		return false
	}
	clean, err := validateHistoryIndexPath(history.IndexPath)
	if err != nil {
		return false
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return false
	}
	indexPath := filepath.Join(brainDir, clean)
	info, err := os.Stat(indexPath)
	if err != nil || !info.Mode().IsRegular() || info.Size() != history.IndexBytes {
		return false
	}
	// Unsafe/unreadable entries are deliberately excluded by the same collector
	// used to build the index. Comparing the safe included set keeps those
	// exclusions fail-closed without forcing an endless rebuild.
	stones, _, err := loadSessionTombstonesChecked(brainDir)
	if err != nil {
		return false
	}
	excludedByPath, err := excludedTranscriptPathsChecked(brainDir, manifest, stones)
	if err != nil {
		return false
	}
	files, err := collectHistorySessionDigests(context.Background(), brainDir, excludedByPath)
	if err != nil {
		return false
	}
	return historyTranscriptFilesFingerprint(files) == history.TranscriptsFingerprint
}

// refreshExportProgressCounts reports the pair the exporter is currently
// counting: its own unit when it has one, checkpoints otherwise, and (0, 0) —
// indeterminate — when it has neither.
func refreshExportProgressCounts(p exportProgress) (int, int) {
	if p.Total > 0 {
		return p.Current, p.Total
	}
	if p.TotalCheckpoints > 0 {
		return p.CurrentCheckpoint, p.TotalCheckpoints
	}
	return 0, 0
}

func refreshExportProgressLabel(p exportProgress) string {
	label := "export sessions"
	if status := strings.TrimSpace(p.Status); status != "" {
		label += ": " + status
	}
	current := p.Current
	total := p.Total
	unit := strings.TrimSpace(p.Unit)
	if total <= 0 {
		current = p.CurrentCheckpoint
		total = p.TotalCheckpoints
		unit = "checkpoint"
	}
	if total <= 0 {
		return label
	}
	if unit == "" {
		unit = "item"
	}
	return fmt.Sprintf("%s: %d/%d %s, %s", label, current, total, pluralUnit(unit, total), pluralCount(p.Sessions, "session"))
}

func pluralUnit(unit string, count int) string {
	if count == 1 {
		return unit
	}
	if strings.HasSuffix(unit, "s") {
		return unit
	}
	return unit + "s"
}

// refreshWorktreeSemanticSkipNote is what `--worktree` owes the reader: the
// stage it silently declined, why, and the only action that actually clears the
// dirty-unindexed state it leaves behind. Neither `refresh --agent none` (which
// refuses to seed uncommitted content) nor `refresh --worktree` (which indexes
// the uncommitted content instead of resolving it) does, so the remedy is git's
// — the same two verbs setupDirtyWorktreeHint names on `status` and `setup`.
func refreshWorktreeSemanticSkipNote(brainCmd string) string {
	return "note: semantic index not rebuilt -- --worktree refreshes seed and docs only;" +
		" commit or stash the working tree, then run `" + brainCmd + " refresh` to index it"
}

// noteDegradedStage prints the named cause of a stage this refresh chose to
// survive rather than abort on.
//
// A progress line has room for a condition ("`entire` is not on PATH"), not for
// a remedy, and when the error is no longer returned the remedy has nowhere
// else to go: a standalone `refresh` has no per-component reporter, so the
// whole sentence vanished and the run printed "semantic index ... failed" with
// no reason at all. `setup` does not use this — its component callback already
// renders detail and hint — so nothing is ever said twice.
	if steps.delta != nil {
		stats, err := steps.delta(ctx)
		if err != nil {
			deltaHealthy = false
			deltaNeedsReconcile = true
			fmt.Fprintf(out, "[watch] short-term memory update failed (continuing): %v\n", err)
		} else {
			// A delta that failed to scan any transcript did NOT fully carry
			// the new work, so it must not defer consolidation.
			deltaHealthy = stats.Failed == 0
			bufferFull = stats.Truncated
			deltaNeedsReconcile = stats.Files > 0 || stats.Failed > 0 || stats.Truncated
			fmt.Fprintf(out, "[watch] short-term memory updated (%d records from %d changed transcripts)\n", stats.Records, stats.Files)
			if stats.Failed > 0 {
				fmt.Fprintf(out, "[watch] short-term memory incomplete: %d transcripts failed to scan; consolidation will repair\n", stats.Failed)
			}
		}
	}
	// Delta state is itself a source-change signal. Do this before the git
	// fingerprint gate so a changed/failed/overflowed export is never stranded
	// in the short-term overlay waiting for an unrelated commit or restart.
	if deltaNeedsReconcile && steps.reconcile != nil {
		if err := steps.reconcile(ctx); err != nil {
			fmt.Fprintf(out, "[watch] memory reconciliation failed (durable overlay retained): %v\n", err)
		} else {
			fmt.Fprintln(out, "[watch] long-term memory reconciliation queued")
		}
	}
	cursor := loadWatchCursor(cursorPath)
	fp := steps.fingerprint(ctx)
	changed := fp != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
	if !changed {
		fmt.Fprintln(out, "[watch] no change; nothing to do")
		return
	}
	// Consolidation throttle: the fingerprint includes checkpoint refs, so an
	// active agent session flips it every turn; without a throttle the heavy
	// full refresh would run every tick exactly when the machine is busiest.
	// A failed delta means nothing carried the new work, so the full refresh is
	// the repair path and must not wait the whole interval (Bugbot PR #78),
	// but it is throttled too, just on a shorter clock. The delta and the full
	// refresh contend for the SAME brain write lock, so an unthrottled repair
	// would fire the heavy path every tick for as long as the delta keeps
	// failing, contending for the very lock that broke it. watchRepairWait
	// escalates after one tick and then backs off to the normal cadence. An
	// overflowed buffer still forces consolidation immediately: recall
	// completeness is at risk, and a successful consolidation clears the
	// overlay, so it cannot repeat the way a failing delta can. The first ever
	// refresh always runs.
	if w.consolidateEvery > 0 && !cursor.LastRefreshAt.IsZero() && !bufferFull {
		wait := w.consolidateEvery
		state := "short-term memory is current"
		if !deltaHealthy {
			wait = watchRepairWait(w, cursor.ConsolidationRepairs)
			state = fmt.Sprintf("short-term memory failed; repair refresh backing off after %d consecutive repairs", cursor.ConsolidationRepairs)
		}
		if since := steps.now().UTC().Sub(cursor.LastRefreshAt); since < wait {
			fmt.Fprintf(out, "[watch] consolidation deferred (%s since last full refresh; due in %s; %s)\n",
				since.Round(time.Second), (wait - since).Round(time.Second), state)
			return
		}
	}
	if err := steps.refresh(ctx); err != nil {
		// Refresh failed: do NOT spend tokens on an unrefreshed brain, and do NOT advance the cursor.
		// The next tick retries the (free) refresh; the gated agent work only ever runs on a brain that
		// was actually refreshed this tick — so a persistent refresh failure can never re-spend.
		fmt.Fprintf(out, "[watch] refresh failed (skipping agent work this tick): %v\n", err)
		return
	}
	reserved, reason, err := reserveWatchAgentSpend(cursorPath, fp, w, agentCalls, steps.now().UTC(), !deltaHealthy)
	if err != nil {
		fmt.Fprintf(out, "[watch] cursor update failed (skipping agent work this tick): %v\n", err)
		return
	}
	fmt.Fprintln(out, "[watch] refreshed (deterministic, no agent tokens)")

	if !w.agentWorkEnabled() {
		return
	}
	if !reserved {
		fmt.Fprintf(out, "[watch] agent work skipped: %s\n", reason)
		return
	}
	// Gated token-spending work: agent seed synthesis and/or distill, at most once per --distill-every,
	// counted against --budget. A transient failure of one step is intentionally best-effort: we still
	// advance the spend cursor + budget below so a failed step retries on the NEXT interval, not every
	// tick (and a step that already burned tokens before failing can't be re-run for free).
	seedAttempted := false
	if w.seedAgent != "none" {
		seedAttempted = true
		if err := steps.seed(ctx); err != nil {
			fmt.Fprintf(out, "[watch] seed synthesis failed: %v\n", err)
		} else {
			fmt.Fprintln(out, "[watch] synthesized seed (agent step; spent tokens)")
		}
	}
	if w.distill {
		switch err := steps.distill(ctx); {
		case errors.Is(err, errDistillPassBusy):
			// When distill was the only agent step, nothing was spent, so nothing
			// may be charged. Hand the window
			// back instead of logging "spent tokens" and going quiet until the
			// next one — otherwise a watcher installed beside `setup`'s
			// hours-long backfill loses its first window (and, if the backfill
			// outlives it, every window) to a pass that never ran.
			// A seed step attempted immediately before this may already have spent
			// tokens even when it returned an error, so its reservation must stay.
			if seedAttempted {
				fmt.Fprintln(out, "[watch] distill skipped: another pass holds this brain; the spend window remains consumed by seed synthesis")
			} else {
				releaseWatchAgentSpend(cursorPath, cursor.LastAgentSpendAt, agentCalls)
				fmt.Fprintln(out, "[watch] distill skipped: another pass holds this brain; the spend window was NOT consumed")
			}
		case err != nil:
			fmt.Fprintf(out, "[watch] distill failed: %v\n", err)
		default:
			fmt.Fprintln(out, "[watch] distilled facts (agent step; spent tokens)")
		}
	}
}

// releaseWatchAgentSpend gives back a window reserved by reserveWatchAgentSpend
// when the gated step turned out to do nothing at all. previous is the
// LastAgentSpendAt read at the top of this tick, so the cursor lands exactly
// where it was; the budget counter is decremented for the same reason. Failures
// are deliberately silent: the worst case is the pre-existing behaviour (a
// window charged for a no-op), and a watcher must never die on cursor
// bookkeeping.
func releaseWatchAgentSpend(cursorPath string, previous time.Time, agentCalls *int) {
	_ = withWatchCursorLock(cursorPath, func() error {
		cursor := loadWatchCursor(cursorPath)
		cursor.LastAgentSpendAt = previous
		if *agentCalls > 0 {
			*agentCalls--
		}
		return saveWatchCursor(cursorPath, cursor)
	})
}

// agentWorkEnabled reports whether any token-spending step is turned on.
func (w watchCommandOptions) agentWorkEnabled() bool {
	return w.distill || w.seedAgent != "none"
}

// watchStepsForRepo builds the per-repo side effects the watch loop drives. refresh is ALWAYS the free
// (seed-agent none) deterministic refresh; seed and distill are the gated token steps. Shared by the
// single-repo `watch` and the workspace fan-out so both stay token-frugal the same way.
func watchStepsForRepo(cmd *cobra.Command, opts Options, w watchCommandOptions, repoDir string, now func() time.Time) watchSteps {
	return watchSteps{
		now:         now,
		fingerprint: func(c context.Context) string { return watchFingerprint(c, opts.Runner, repoDir) },
		delta:       func(c context.Context) (shortTermStats, error) { return watchShortTermDelta(c, cmd, opts, repoDir) },
		reconcile: func(c context.Context) error {
			_, warning, err := reconcileMemoryAndLaunch(c, opts, repoDir, "watch")
			if warning != "" {
				fmt.Fprintf(cmd.ErrOrStderr(), "warning: memory coordinator: %s\n", warning)
			}
			return err
		},
		refresh: func(c context.Context) error { return watchDeterministicRefresh(c, cmd, opts, repoDir) },
		seed:    func(c context.Context) error { return watchSeed(c, cmd, opts, w, repoDir) },
		distill: func(c context.Context) error { return watchDistill(c, cmd, opts, w, repoDir) },
	}
}

// watchShortTermDelta runs the short-term memory path for one repo: quiet
// (output discarded; the tick logs one summary line), deterministic, and
// token-free. The returned stats let the tick escalate to consolidation when
// the buffer overflows.
func watchShortTermDelta(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string) (shortTermStats, error) {
	perRepo := opts
	perRepo.Env.RepoRoot = repoDir
	deltaCmd := &cobra.Command{Use: "delta"}
	deltaCmd.SetOut(io.Discard)
	deltaCmd.SetErr(io.Discard)
	deltaCmd.SetContext(ctx)
	return runRefreshDeltaStats(deltaCmd, perRepo, true)
}

// watchShouldSpend decides whether the token-spending agent work (seed and/or distill) runs this tick:
// only when at least one is enabled AND --distill-every has elapsed since the last agent spend
// (cursor-tracked across restarts) AND the --budget cap is not yet reached. This is the structural
// token-frugality guarantee — it bounds seed synthesis exactly like distill.
func watchShouldSpend(w watchCommandOptions, cursor watchCursor, agentCalls int, now time.Time) (bool, string) {
	if !w.agentWorkEnabled() {
		return false, "no agent steps enabled"
	}
	if !(cursor.LastAgentSpendAt.IsZero() || now.Sub(cursor.LastAgentSpendAt) >= w.distillEvery) {
		return false, "--distill-every not elapsed"
	}
	if w.budget > 0 && agentCalls >= w.budget {
		return false, fmt.Sprintf("--budget %d reached", w.budget)
	}
	return true, ""
}

// watchRepairWait is the minimum time between full consolidations while the
// short-term delta is failing. It starts at one tick (a transient delta failure
// repairs on the very next pass) and doubles per consecutive repair up to the
// normal --consolidate-every, so a persistently failing delta degrades to the
// ordinary consolidation cadence instead of thrashing the shared brain write
// lock on every tick.
func watchRepairWait(w watchCommandOptions, repairs int) time.Duration {
	wait := w.interval
	if wait <= 0 {
		wait = time.Minute
	}
	if repairs > watchRepairBackoffMax {
		repairs = watchRepairBackoffMax
	}
	for i := 0; i < repairs && wait < w.consolidateEvery; i++ {
		wait *= 2
	}
	if wait > w.consolidateEvery {
		wait = w.consolidateEvery
	}
	return wait
}

// reserveWatchAgentSpend advances the refresh cursor after a successful full
// refresh and decides whether the gated token work may run. repair reports
// whether THIS refresh ran early because the short-term delta failed; it drives
// the watchRepairWait backoff and is cleared by the first healthy delta.
func reserveWatchAgentSpend(cursorPath, fingerprint string, w watchCommandOptions, agentCalls *int, now time.Time, repair bool) (bool, string, error) {
	var cursor watchCursor
	var reserved bool
	var reason string
	err := withWatchCursorLock(cursorPath, func() error {
		cursor = loadWatchCursor(cursorPath)
		changed := fingerprint != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
		if changed {
			cursor.LastFingerprint = fingerprint
			cursor.LastRefreshAt = now
			if repair {
				if cursor.ConsolidationRepairs < watchRepairBackoffMax {
					cursor.ConsolidationRepairs++
				}
			} else {
				cursor.ConsolidationRepairs = 0
			}
		}
		if !w.agentWorkEnabled() {
			if changed {
				return saveWatchCursor(cursorPath, cursor)
			}
			return nil
		}
		ok, skipReason := watchShouldSpend(w, cursor, *agentCalls, now)
		if !ok {
			reason = skipReason
			if changed {
				return saveWatchCursor(cursorPath, cursor)
			}
			return nil
		}
		cursor.LastAgentSpendAt = now
		*agentCalls++
		reserved = true
		return saveWatchCursor(cursorPath, cursor)
	})
	return reserved, reason, err
}

func withWatchCursorLock(cursorPath string, fn func() error) error {
	root := filepath.Dir(cursorPath)
	if info, err := os.Lstat(root); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("watch cursor directory must not be a symlink: %s", root)
	} else if err != nil && !os.IsNotExist(err) {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(root, brainLockDirName); err != nil {
