package cli

import (
	"context"
	"io"
	"path/filepath"
	"testing"
	"time"
)

func TestWatchDeferredWorkRetriesWithoutCommit(t *testing.T) {
	for _, busy := range []bool{false, true} {
		t.Run(map[bool]string{false: "interval_deferred", true: "busy_distill"}[busy], func(t *testing.T) {
			p := filepath.Join(t.TempDir(), "watch.json")
			now := time.Date(2026, 8, 8, 12, 0, 0, 0, time.UTC)
			w := defaultWatchOptions()
			w.distill = true
			w.consolidateEvery = 0
			if !busy {
				if e := saveWatchCursor(p, watchCursor{LastFingerprint: "old", LastRefreshAt: now.Add(-time.Hour), LastAgentSpendAt: now.Add(-time.Hour)}); e != nil {
					t.Fatal(e)
				}
			}
			calls, distills := 0, 0
			s := watchSteps{now: func() time.Time { return now }, fingerprint: func(context.Context) string { return "new" }, refresh: func(context.Context) error { return nil }, distill: func(context.Context) error {
				distills++
				if busy {
					return errDistillPassBusy
				}
				return nil
			}}
			watchTick(context.Background(), io.Discard, w, p, s, &calls)
			before := distills
			now = now.Add(48 * time.Hour)
			watchTick(context.Background(), io.Discard, w, p, s, &calls)
			if distills != before+1 {
				t.Fatalf("due work not retried: before=%d after=%d", before, distills)
			}
		})
	}
}
package cli

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestGenerationAllocationStopsOnPermissionError(t *testing.T) {
	root := t.TempDir()
	if err := os.Chmod(root, 0200); err != nil {
		t.Fatal(err)
	}
	defer os.Chmod(root, 0700)
	if _, err := os.Lstat(filepath.Join(root, "id")); !os.IsPermission(err) {
		t.Skipf("requires non-root permission enforcement: %v", err)
	}
	done := make(chan error, 1)
	go func() { _, err := semanticAvailableGenerationID(root, "id", "suffix"); done <- err }()
	select {
	case got := <-done:
		if !os.IsPermission(got) {
			t.Fatalf("expected permission failure, got %v", got)
		}
	case <-time.After(100 * time.Millisecond):
		os.Chmod(root, 0700)
		select {
		case got := <-done:
			t.Errorf("looped until permissions were repaired; returned %v", got)
		case <-time.After(time.Second):
			t.Error("did not recover")
		}
	}
}
