// watchDeterministicRefresh refreshes sessions + semantic state with the seed
// agent ALWAYS "none", then durably reconciles long-term conversation work.
// The coordinator owns projection publication, retries, and crash recovery;
// watch only nudges it. Agent seed synthesis remains a separate gated step.
func watchDeterministicRefresh(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string) error {
	return watchDeterministicRefreshComponents(ctx, cmd, opts, repoDir, watchTickBuildsHistoryProjection, nil)
}

// watchDeterministicRefreshComponents is the same free path with an optional
// per-component reporter. With a reporter the refresh is BEST-EFFORT: every
// component is attempted and its outcome reported (err == nil means built)
// instead of the first failure aborting the build. `setup` uses it so a single
// broken source degrades the brain rather than killing first-run onboarding;
// callers that pass nil keep the strict all-or-nothing behaviour.
//
// historyIndex separates the two callers that were previously identical. A
// watch TICK passes false: it runs every few minutes, the per-tick delta
// already makes new conversations recallable, and the coordinator consolidates
// the durable projection on its own schedule. `setup` passes true, because it
// is a one-shot onboarding build (the same shape as a manual `refresh`, which
// has always defaulted history on) and it ends by telling the user to run
// `entire-brain brief`. With history unbuilt that brief silently drops its
// transcript half and prints "history index missing" instead — setup's own
// recommended next command, answering with a warning about setup's own output.
// watchDeterministicRefreshOptions is the free path's refresh configuration,
// built here rather than inline so both callers' intent — above all whether the
// history projection is built — is readable and testable in one place.
func watchDeterministicRefreshOptions(historyIndex bool) refreshCommandOptions {
	return refreshCommandOptions{
		outputDir:       defaultExportDir,
		checkpointLimit: defaultCheckpointLimit,
		entireBinary:    "entire",
		graphBinary:     "entire",
		scope:           exportScopeAll,
		// A tick must not bypass the durable work ledger: the per-tick delta
		// already makes new conversations recallable while the coordinator
		// consolidates asynchronously. A one-shot onboarding build has no next
		// tick to wait for, so `setup` asks for it explicitly.
		historyIndex: historyIndex,
		semantic:     true,
		seed: seedCommandOptions{
			includeTests:       true,
			maxFileBytes:       defaultSeedMaxFileBytes,
			maxFiles:           defaultSeedMaxFiles,
			format:             "markdown+json",
			agent:              "none", // free: deterministic seed only; agent seed is gated via watchSeed
			agentQuickTimeout:  2 * time.Minute,
			agentDeepTimeout:   10 * time.Minute,
			agentTimeoutAction: "keep-quick",
			agentMaxInputBytes: defaultAgentMaxInput,
		},
	}
}

func watchDeterministicRefreshComponents(ctx context.Context, cmd *cobra.Command, opts Options, repoDir string, historyIndex bool, component func(name string, err error)) error {
	perRepo := opts
	perRepo.Env.RepoRoot = repoDir
	refreshOpts := watchDeterministicRefreshOptions(historyIndex)
	refreshOpts.component = component
	sub := &cobra.Command{}
	sub.SetContext(ctx)
	sub.SetOut(cmd.OutOrStdout())
	sub.SetErr(cmd.ErrOrStderr())
	if err := runRefresh(ctx, sub, perRepo, refreshOpts); err != nil {
		return err
	}
	// Deterministic and token-free, like everything else in this step: index any
	// checkpoint commits that landed since the entity index's high-water mark.
	// Bounded and failure-silent — a missing `entire graph` provider must never
	// fail a tick that otherwise refreshed the brain. Under a reporter it is one
	// more degradable component, so `setup --json`, `status` and `doctor` can
	// name it instead of losing the reason to a discarded stderr line; with no
	// reporter the strict watch path keeps its warning and carries on exactly as
	// before.
	entityErr := refreshEntityIndexQuietly(ctx, perRepo, repoDir)
	switch {
	case component != nil:
		component(brainComponentEntities, entityErr)
	case entityErr != nil:
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: entity index refresh skipped: %v\n", entityErr)
	}
	_, warning, err := reconcileMemoryAndLaunch(ctx, perRepo, repoDir, "watch")
	// discardManifestThisBuildCannotRewrite above); only the launch failure is
	// forgiven, and only because there is nothing to fix in the brain.
	hostCLIAbsent := hostCLIMissing(exportErr, refreshOpts.entireBinary)
	if hostCLIAbsent {
		exportErr = hostCLIMissingExportError(exportErr, refreshOpts.entireBinary)
	}
	// The sessions component is reported exactly once, here, where the export
	// outcome and the seed fallback are both known: a failed export that a seed
	// baseline papers over is still a failed sessions source, and saying so is
	// the whole point of a per-component report.
	var degradedSessions error
	if !refreshOpts.skipSessions {
		if exportErr != nil && !needSeed && !hostCLIAbsent {
			finishExportTask(exportErr)
			if stage(brainComponentSessions, exportErr) {
				return exportErr
			}
		} else if stage(brainComponentSessions, exportErr) {
			degradedSessions = exportErr
		}
	}
	if exportErr == nil || needSeed || hostCLIAbsent {
		if exportErr != nil {
			updateExportTask(refreshExportDegradedLabel(hostCLIAbsent, needSeed))
		}
		finishExportTask(nil)
	}
	// After the stage's own terminal line, not before it: the progress reporter
	// holds one buffered line per phase, so a note emitted at the decision point
	// lands in the middle of the stage it is explaining.
	noteDegradedStage(cmd.ErrOrStderr(), brainComponentSessions, degradedSessions)
	switch {
	case seedProbeErr != nil:
		// One line: this is a parenthesised progress note, and a named repository
		// condition carries its remedy on the lines after the first, which the
		// terminal error still prints in full.
		progress.Skip("seed baseline: freshness unknown (" + firstErrorLine(seedProbeErr) + ")")
		if stage(brainComponentSeed, seedProbeErr) {
			return seedProbeErr
		}
	case needSeed:
		seedTask := progress.Begin("seed baseline")
		seedCmd := &cobra.Command{Use: "seed"}
		seedCmd.SetOut(io.Discard)
		seedCmd.SetErr(io.Discard)
		seedOpts := refreshOpts.seed
		seedOpts.update = true
		seedOpts.outputExplicit = outputExplicit
		seedOpts.progress = func(phase string) {
			seedTask.Update("seed baseline: " + phase)
		}
		if outputExplicit {
			seedOpts.outputDir = brainDir
		}
		seedErr := runSeed(ctx, seedCmd, opts, seedOpts, repoDir)
		// Seed may have updated the manifest before a later best-effort step
		// failed. History freshness must use the state now on disk in either
		// outcome, not the snapshot loaded before seed ran.
		manifest, _ = loadBrainManifest(brainDir)
		if seedErr != nil {
			seedTask.Finish(seedErr)
			if stage(brainComponentSeed, seedErr) {
				return seedErr
			}
		} else {
			seedTask.Update(refreshSeedLabel(manifest))
			seedTask.Finish(nil)
			stage(brainComponentSeed, nil)
		}
	default:
		progress.Skip(refreshSeedLabel(manifest))
		stage(brainComponentSeed, nil)
	}
	// The projector reads the brain directory directly, and on a first run where
	// EVERY source failed there is no brain directory to read: a repo enabled a
	// minute ago has no sessions to export, and if the worktree is also dirty
	// (which `entire enable` leaves it) the seed baseline does not build either.
	// Running the projector anyway answered "you have no sessions yet" with a
	// second, rawer line naming an internal path and no remedy --
	// "lstat <brainDir>: no such file or directory". An empty history index over
	// a brain directory that DOES exist is still built, as before.
	if refreshOpts.historyIndex && !historyProjectionTargetExists(brainDir) {
		progress.Skip("history index: skipped, no brain directory was built")
	} else if refreshOpts.historyIndex && (refreshOpts.force || !historyIndexCurrent(brainDir, manifest)) {
		historyTask := progress.Begin("history index")
		historyProgress := func(done, total int) {
			if total <= 0 {
				return
			}
			historyTask.SetProgress(done, total)
			historyTask.Update(fmt.Sprintf("history index: %d/%d %s scanned", done, total, pluralUnit("session", total)))
		}
		historySource, err := writeBrainHistoryIndexAndSourceContext(ctx, brainDir, opts.Now().UTC(), historyProgress)
		if err != nil {
			historyTask.Finish(err)
			if stage(brainComponentHistory, err) {
				return err
			}
		} else {
			historyTask.Update(refreshHistoryLabel(historySource))
			historyTask.Finish(nil)
			manifest, _ = loadBrainManifest(brainDir)
			stage(brainComponentHistory, nil)
		}
	} else if refreshOpts.historyIndex {
		progress.Skip(refreshHistoryLabel(existingHistorySource(manifest)))
		stage(brainComponentHistory, nil)
	}
	// History vectors: the persisted semantic arm behind the fusion gate (see
	// history_vec.go). The stage exists only when the user has opted into an
	// external embedder — without ENTIRE_BRAIN_EMBEDDER there is no line at
	// all, so the default refresh output is unchanged. The first sync of a
	// large repo embeds every record (potentially hours, one HTTP embed at a
	// time); progress is batched to disk, so interrupting and re-running
	// refresh resumes rather than restarts.
	if refreshOpts.historyIndex && strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")) != "" &&
		manifest != nil && manifest.Sources != nil && manifest.Sources.History != nil {
		e := historySemanticEmbedder(defaultEmbedder())
		store, storeOK := historyVectorStoreFor(brainDir, e)
		switch {
		case e == nil:
			// Opt-in set but not honored (server unreachable → Model2Vec
			// fallback, which is a closed negative on history). defaultEmbedder
			// already printed the fallback warning.
			progress.Skip("history vectors: embed server unavailable")
		case !storeOK:
			progress.Skip("history vectors: requires the brain_cgo build")
		default:
			_ = store // availability was checked above; the guarded writer reopens it.
			vecTask := progress.Begin("history vectors")
			vectors, serr := syncMemoryProjectionVectorsFully(ctx, brainDir, opts.Now().UTC(), e, func(current memoryVectorSyncPass) {
				vecTask.Update(fmt.Sprintf("history vectors: %d new %s embedded", current.HistoryAdded, pluralUnit("record", current.HistoryAdded)))
			})
			if serr != nil {
				vecTask.Finish(serr)
				if stage(brainComponentHistoryVectors, serr) {
					return serr
				}
				break
			}
			vecTask.Update(fmt.Sprintf("history vectors: %d embedded, %d pruned (%d total)", vectors.HistoryAdded, vectors.HistoryDropped, vectors.HistoryTotal))
			vecTask.Finish(nil)
			stage(brainComponentHistoryVectors, nil)
			// Conversation vectors ride the same stage and gate but live in
			// their own store (separate identity; general history KNN never
			// spends budget on exchanges). Skipped silently when the store is
			// unavailable; the history stage above already reported why.
			if _, convOK := newConversationVectorStore(brainDir, conversationVectorModelID(e.ID()), e.Dim()); convOK {
				convTask := progress.Begin("conversation vectors")
				convTask.Update(fmt.Sprintf("conversation vectors: %d embedded, %d pruned (%d total)", vectors.ConversationAdded, vectors.ConversationDrop, vectors.ConversationTotal))
				convTask.Finish(nil)
			}
		}
	}
	// Doc index: retrievable chunks of the brain's own markdown (seed summaries
	// + copied repo docs). It derives from seed, not history, so gate it on its own
	// inputs — rebuild when seed ran, when the docs source is missing, on --force,
	// or alongside a history-index build — never silently skip it just because
	// --history-index=false.
	docsMissing := manifest == nil || manifest.Sources == nil || manifest.Sources.Docs == nil
	if refreshOpts.historyIndex || needSeed || docsMissing || refreshOpts.force {
		docTask := progress.Begin("doc index")
		// A doc-index write failure (permissions, disk full, corrupt manifest) is a
		// real error: fail the refresh like the history index does, so automation
		// relying on the exit status isn't told success on an incomplete brain.
		// (A missing seed is not an error — writeDocIndexAndSource writes an empty
		// index in that case.)
		docSource, derr := writeDocIndexAndSource(brainDir, opts.Now().UTC())
		if derr != nil {
			docTask.Finish(derr)
			if stage(brainComponentDocs, derr) {
				return derr
			}
		} else {
			docLabel := fmt.Sprintf("doc index: %d chunks / %d files", docSource.Records, docSource.Files)
			if n := len(docSource.Warnings); n > 0 {
				docLabel += fmt.Sprintf(" (%d %s)", n, pluralUnit("warning", n))
			}
			docTask.Update(docLabel)
			docTask.Finish(nil)
			manifest, _ = loadBrainManifest(brainDir)
			stage(brainComponentDocs, nil)
		}
	} else {
		stage(brainComponentDocs, nil)
	}
	if refreshOpts.semantic {
		semanticCheckTask := progress.Begin(refreshSemanticCheckLabel(manifest))
		semanticWorktree := refreshOpts.semanticWorktree
		// Both semantic failure paths below are forgiven for exactly one
		// reason: the provider IS the host CLI and the host CLI is not
		// installed. Evaluated once, before either, so the two stages cannot
		// disagree about the machine they are running on.
		semanticHostAbsent := hostCLISemanticProviderAbsent(refreshOpts.graphBinary)
		needSemantic, identityWarning, err := semanticRefreshNeeded(ctx, opts, brainDir, repoDir, manifest, semanticWorktree, refreshOpts.graphBinary)
		switch {
		case err != nil:
			semanticCheckTask.Finish(err)
			if stage(brainComponentSemantic, err) {
				if !semanticHostAbsent {
					return err
				}
				noteDegradedStage(cmd.ErrOrStderr(), brainComponentSemantic, err)
			}
		default:
			if identityWarning != "" {
				fmt.Fprintf(cmd.ErrOrStderr(), "warning: %s\n", identityWarning)
			}
			if !needSemantic {
				label := ": current"
				if identityWarning != "" {
					label = ": source unchanged; provider identity unverified"
				}
				semanticCheckTask.Update(refreshSemanticCheckLabel(manifest) + label)
			}
			semanticCheckTask.Finish(nil)
			if refreshOpts.force {
				needSemantic = true
			}
			if needSemantic {
				semanticTask := progress.Begin("semantic index")
				indexCmd := &cobra.Command{Use: "index"}
				indexCmd.SetOut(io.Discard)
				indexCmd.SetErr(io.Discard)
				semanticProgress := func(phase string) {
					semanticTask.Update("semantic index: " + phase)
				}
				// The provider does not announce how many files it is about to
				// emit, so the bar is scaled by the PREVIOUS generation's file
				// count. That is an estimate and is treated as one: a repo that
				// grew simply pins the bar at full for the tail of the run, and
				// a first-ever index (no previous count) gets an honest
				// indeterminate spinner instead of a fabricated fraction.
				expectedFiles := 0
				if previous := existingSemanticSource(manifest); previous != nil {
					expectedFiles = previous.Files
				}
				semanticCounts := func(files, _, _ int) {
					semanticTask.SetProgress(files, expectedFiles)
				}
				if err := runSemanticIndex(ctx, indexCmd, opts, semanticIndexOptions{force: true, graphBinary: refreshOpts.graphBinary, worktree: semanticWorktree, outputDir: brainDir, outputExplicit: outputExplicit, progress: semanticProgress, progressCounts: semanticCounts}, repoDir); err != nil {
					semanticTask.Finish(err)
					if stage(brainComponentSemantic, err) {
						if !semanticHostAbsent {
							return err
						}
						noteDegradedStage(cmd.ErrOrStderr(), brainComponentSemantic, err)
					}
				} else {
					manifest, _ = loadBrainManifest(brainDir)
					semanticTask.Update(refreshSemanticLabel(existingSemanticSource(manifest)))
					semanticTask.Finish(nil)
					stage(brainComponentSemantic, nil)
				}
			} else {
				progress.Skip(refreshSemanticLabel(existingSemanticSource(manifest)))
				stage(brainComponentSemantic, nil)
			}
		}
	} else if refreshOpts.semanticWorktreeSkip {
		progress.Skip("semantic index: skipped, --worktree refreshes seed and docs only")
## F6 — P2: Refresh orchestration combines too many responsibilities and hides policy in callbacks

**Confidence: high as a maintainability finding; no additional runtime defect asserted.**

Location: [internal/cli/refresh.go](/Users/thomi/.codex/worktrees/5d33/entire-brain/internal/cli/refresh.go:123).

`runRefresh` spans 494 lines and combines option validation, output handling, export, seeding, history, vectors, documents, semantic indexing, branches, fact reclassification, patterns, progress rendering, and final status. It repeatedly constructs Cobra commands as internal adapters and interleaves phase outcomes with mutable manifest reloads.

The local helper named `stage` both reports an outcome and returns whether to abort. Merely installing the `component` callback changes that abort policy. A reader must understand this hidden contract at every `if stage(...)` branch.

**Graph evidence:** the impact analysis identifies CLI, MCP, path, and watcher callers and 59 callees, including library/external endpoints. This is shared orchestration, not a local cosmetic change. See [refresh impact](/Users/thomi/.codex/visualizations/2026/09/18/01a0b6ce-e2ad-7853-bb2f-19731062a2c9/code-quality-audit/evidence/audit-impact-refresh.txt).

**Recommended remedy:** extract cohesive phase operations with explicit outcomes, keep fail-fast versus best-effort policy in the orchestrator, and leave rendering at the boundary. A name such as `reportStageAndShouldAbort` would clarify the current helper even before structural work. Avoid introducing a generic workflow framework.



