	replaceRefreshComponentDirWithFile(t, brainDir, historyDirName, historyMarker)
	replaceRefreshComponentDirWithFile(t, brainDir, docDirName, docsMarker)

	outcomes := map[string]error{}
	cmd := &cobra.Command{}
