// semanticRecordedArtifactsReadable re-reads the two files the recorded
// semantic source points at -- the provider snapshot and the derived SQLite
// store -- and reports the first that will not load. It answers "is what the
// manifest claims actually still there and openable", which is the half of
// freshness that a commit comparison cannot see.
func semanticRecordedArtifactsReadable(brainDir string, source *semanticSourceManifest) error {
	if source.SnapshotPath == "" {
		return errors.New("semantic snapshot_path is missing")
	}
	snapshot, err := validateSemanticSnapshotPath(source.SnapshotPath)
	if err != nil {
		return err
	}
	if err := rejectSymlinkPathComponents(brainDir, snapshot); err != nil {
		return err
	}
	info, err := os.Lstat(filepath.Join(brainDir, snapshot))
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("semantic snapshot must be a regular file: %s", source.SnapshotPath)
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return err
	}
	header, counts, err := readSemanticSnapshotSummary(filepath.Join(brainDir, snapshot), manifest.RepoKey)
	if err != nil {
		return err
	}
	if err := validateSemanticSourceMatchesSnapshot(source, header, counts); err != nil {
		return err
	}
	if source.StorePath == "" {
		return nil
	}
	generation, err := validateSemanticGenerationPath(source.GenerationPath)
	if err != nil {
		return err
	}
	store, err := validateSemanticGenerationFilePath(source.StorePath, generation, semanticSQLiteName)
	if err != nil {
		return err
	}
	if err := rejectSymlinkPathComponents(brainDir, store); err != nil {
		return err
	}
	return validateSemanticSQLiteStore(filepath.Join(brainDir, store), source.Symbols, source.Relations)
}

// semanticIndexStageDeadline stops an index at a stage boundary when its caller's
// deadline has already passed.
//
// A deadline that is only consulted after the work finishes is not a deadline.
// brain_index_repository advertises a 60 second cap and returned at ~113 seconds,
// because nothing between "verify the provider" and "write the manifest" ever
// asked whether it was still wanted -- the cap chose the error, the work chose
// the wall clock. Checking at each boundary, plus inside the store build's own
// row loop (buildSemanticGeneration), means an expired index stops at the next
// boundary instead of running to completion and then being thrown away.
//
// The stage name is in the error so a caller reading a debug log can see WHERE
// the time went, not just that time ran out.
func semanticIndexStageDeadline(ctx context.Context, stage string) error {
		result.Reason = "authored fact has no retained source anchor"
		return result
	}

	session, sessionFound, sessionCheck := v.verifyExportedSession(anchor, factBranch)
	result.addCheck(sessionCheck)
	if !sessionFound {
		result.Reason = sessionCheck.Reason
		return result
	}
	if strings.TrimSpace(anchor.TurnID) != "" {
		result.addCheck(verifyTurnID(session, anchor.TurnID))
	}
	if strings.TrimSpace(anchor.CheckpointID) != "" {
		result.addCheck(v.verifyCheckpoint(anchor.CheckpointID))
	}

	transcriptRel := strings.TrimSpace(anchor.Transcript)
	if transcriptRel == "" {
		transcriptRel = session.TranscriptPath
	}
	transcriptContent := ""
	transcriptRead := false
	if transcriptRel == "" {
		result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: "anchor has no transcript path"})
	} else {
		if session.TranscriptPath != "" && anchor.Transcript != "" && filepath.ToSlash(session.TranscriptPath) != filepath.ToSlash(anchor.Transcript) {
			result.addCheck(verifyCheck{Name: "transcript_path", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("exported session now points at %s", session.TranscriptPath)})
		}
		data, err := readCanonicalHistoryTranscript(v.ctx, v.brainDir, transcriptRel)
		if err != nil {
			result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: err.Error()})
		} else {
			transcriptContent = string(data)
			transcriptRead = true
			result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictVerified, Reason: transcriptRel})
		}
	}
	if anchor.Line > 0 && transcriptRead {
		line, ok := transcriptLine(transcriptContent, anchor.Line)
		if !ok {
			result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictOrphaned, Reason: fmt.Sprintf("line %d is outside transcript", anchor.Line)})
		} else {
			result.LineExcerpt = truncateString(strings.Join(strings.Fields(line), " "), 200)
			result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictVerified, Reason: fmt.Sprintf("line %d resolved", anchor.Line)})
		}
	}
	if strings.TrimSpace(anchor.CheckpointID) != "" && transcriptRead {
		result.addCheck(v.verifyCheckpointTranscript(anchor, session, transcriptContent))
	}
	result.Reason = reasonForAnchorVerdict(result.Verdict)
	return result
}

