item.stdout:
func memoryInventoryIssueState(issues []memoryStateIssue) (string, string) {
	priority := map[string]int{
		memoryErrMigrationRequired:  1,
		memoryErrStateCorrupt:       2,
		memoryErrUnsupportedVersion: 3,
		memoryErrStateUnsafe:        4,
	}
	selected, selectedPriority := memoryErrStateCorrupt, -1
	for _, issue := range issues {
		if p := priority[issue.Code]; p > selectedPriority {
			selected, selectedPriority = issue.Code, p
		}
	}
	switch selected {
	case memoryErrMigrationRequired:
		return memoryErrMigrationRequired, selected
	case memoryErrUnsupportedVersion:
		return "unsupported", selected
	case memoryErrStateUnsafe:
		return "unsafe", selected
	default:
		return "corrupt", selected
	}
}

func memoryVectorProgressHealth(brainDir string, source *historySourceManifest) map[string]any {
	health := map[string]any{
		"path":                     memoryVectorProgressRel,
		"present":                  false,
		"state":                    "absent",
		"schema_state":             "absent",
		"supported_schema_version": memoryVectorSchema,
		"action":                   "none",
	}
	progress, present, err := loadMemoryVectorProgress(brainDir)
	health["present"] = present
	if err != nil {
		code := memoryErrorCode(err)
		state := "corrupt"
		progress.Skip("semantic index: skipped, --worktree refreshes seed and docs only")
	} else {
		progress.Skip("semantic index")
	}
	if refreshOpts.allBranches {
		finishBranches := progress.Step("branch overlays")
		if err := runSemanticRefreshAllBranches(ctx, opts, refreshOpts, repoDir); err != nil {
			finishBranches(err)
			if stage(brainComponentBranches, err) {
				return err
			}
		} else {
			finishBranches(nil)
			stage(brainComponentBranches, nil)
		}
	}
	// Backfill deterministic fact kinds/locus when a fact store exists, so a kind
	// distilled before kind-storage (or otherwise left empty) is repaired here
	// rather than needing a manual `facts reclassify`. No agent, no tokens.
	manifest, _ = loadBrainManifest(brainDir)
	if manifest != nil && manifest.Sources != nil && manifest.Sources.Facts != nil {
		finishReclass := progress.Step("reclassify facts")
		if _, err := reclassifyAllFactBranches(brainDir, opts.Now().UTC()); err != nil {
			finishReclass(err)
			if stage(brainComponentFacts, err) {
				return err
			}
		} else {
			finishReclass(nil)
			stage(brainComponentFacts, nil)
		}
	}
	// Pattern layer (episodes -> tasks/procedures/practices). Deterministic and
	// token-free, so it is part of the normal refresh — the user never has to
	// discover a second build command. Rebuilt when sessions changed or --force.
	manifest, _ = loadBrainManifest(brainDir)
	if !refreshOpts.skipSessions && manifest != nil && manifest.Sources != nil && manifest.Sources.Sessions != nil {
		finishPatterns := progress.Step("pattern layer")
		if _, err := refreshPatternLayer(brainDir, refreshOpts.force, opts.Now().UTC()); err != nil {
			finishPatterns(err)
			if stage(brainComponentPatterns, err) {
				return err
			}
		} else {
			// The internal pattern corpus is a rebuildable cache; a corpus failure must
			// not break the rest of the brain, so it is a warning here (the explicit
			// `patterns refresh` is the stricter surface that fails on corpus errors).
			if cerr := buildPatternCorpus(brainDir, opts.Now().UTC()); cerr != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "warning: pattern corpus: %v\n", cerr)
			}
			finishPatterns(nil)
			stage(brainComponentPatterns, nil)
		}
	}
	// On STDOUT, beside the success line it qualifies. `--worktree` turning the
	// semantic stage off is deliberate, and `setup`'s documented exit-0-on-partial
	// is the precedent for keeping the exit code at 0 -- but setup earns that by
	// naming every component it skipped, and this named none. The skip went to
	// stderr as a bare "semantic index skipped" while stdout said "refreshed
	// brain" and the status verdict underneath went on reporting the same
	// degradation, so the one state no command clears was the one state nothing
	// explained. An exit code cannot carry the sentence a reader needs here; the
	// sentence can.
	if refreshOpts.semanticWorktreeSkip {
		printAroundLiveLine(cmd.OutOrStdout(), "%s\n", refreshWorktreeSemanticSkipNote(setupCommandPrefix(os.LookupEnv)))
	}
	printAroundLiveLine(cmd.OutOrStdout(), "refreshed brain: %s\n", brainDir)
	if refreshOpts.statusAfter && !outputExplicit {
		statusCmd := &cobra.Command{Use: "status"}
		statusCmd.SetOut(cmd.OutOrStdout())
		statusCmd.SetErr(cmd.ErrOrStderr())
		if err := runAgentStatus(ctx, statusCmd, opts, agentStatusOptions{}, repoDir); err != nil {
			return fmt.Errorf("status after refresh: %w", err)
		}
	}
	return nil
}

// historyProjectionTargetExists reports whether the brain directory the history
// projector reads is actually there. See the call site in runRefresh.
func historyProjectionTargetExists(brainDir string) bool {
package cli

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestVerifyEmptyTranscriptCannotResolveLine(t *testing.T) {
	b := t.TempDir()
	rel := "sessions/empty.jsonl"
	if e := os.MkdirAll(filepath.Join(b, "sessions"), 0700); e != nil {
		t.Fatal(e)
	}
	if e := os.WriteFile(filepath.Join(b, rel), nil, 0600); e != nil {
		t.Fatal(e)
	}
	v := verifyContext{ctx: context.Background(), brainDir: b, manifest: &exportManifest{Sources: &brainSources{Sessions: &sessionSourceManifest{Sessions: []exportSession{{SessionID: "empty", TranscriptPath: rel}}}}}}
	got := v.verifyAnchor(factAnchor{SessionID: "empty", Transcript: rel, Line: 42}, "")
	t.Logf("result=%+v", got)
	if got.Verdict == verifyVerdictVerified {
		t.Fatal("line 42 of empty transcript verified")
	}
}
package cli

import (
	"fmt"
	"testing"
)

var receiptBenchmarkResult projectionReceipt

func BenchmarkProjectionReceiptLookup(b *testing.B) {
	for _, n := range []int{1000, 10000, 20000} {
		b.Run(fmt.Sprint(n), func(b *testing.B) {
			s := projectionState{Sessions: make([]projectionReceipt, n)}
			for i := range s.Sessions {
				s.Sessions[i].SessionRef = fmt.Sprintf("conversation-session:%08d", i)
			}
			b.ResetTimer()
			for k := 0; k < b.N; k++ {
				for _, r := range s.Sessions {
					receiptBenchmarkResult, _ = s.receiptFor(r.SessionRef)
				}
			}
		})
	}
}
	// name it instead of losing the reason to a discarded stderr line; with no
	// reporter the strict watch path keeps its warning and carries on exactly as
	// before.
	entityErr := refreshEntityIndexQuietly(ctx, perRepo, repoDir)
	switch {
