 case "invalid": data=[]byte("not a semantic snapshot")
 case "truncated": data=data[:bytes.IndexByte(data,'\\n')+1]
 case "wrong_commit": data=bytes.Replace(data,[]byte(source.Commit),[]byte("othercommit"),1)
 }
 if err:=os.WriteFile(path,data,0600);err!=nil{t.Fatal(err)}
 if current(){t.Fatal("damaged snapshot accepted as current")}
 })
 }
 }
}
