		epID := "episode:" + hexSHA(repoKey+"\x00"+filepath.ToSlash(rel)+"\x00"+strconv.Itoa(ord)+"\x00"+strconv.Itoa(startLine))
		epKey := repoKey + "/" + filepath.ToSlash(rel) + "#" + strconv.Itoa(ord)

		if _, err := tx.Exec(`INSERT INTO episodes
