package cli

import (
	"database/sql"
	"math"
	"sort"
	"strconv"
	"strings"
)

// Deep dossiers (Pattern Consolidation v2, Priority 4).
//
// A deep dossier is a BOUNDED but evidence-deep export of a pattern's backing
// episodes — every backing episode resolved by stable episode_key (capped at
// deepMaxEpisodes anchors), the top deepExcerptEpisodes carrying capped, redacted
// transcript span excerpts, not the 3 sampled anchors a shallow dossier stores —
// stratified corrected/failed first so the verifier reasons over failures and
// recoveries. It is assembled deterministically and token-free; the optional deep
// verifier (pattern_verify.go) is the only agent step and runs solely through the
// explicit `patterns verify --deep`. The fingerprint covers the full backing-set
// identity (every episode_key + outcome), so it changes (and the cached verdict
// goes stale) whenever any supporting episode moves.

const deepSchemaVersion = 1
const deepMaxEpisodes = 40    // cap the full set handed onward
const deepMaxParameters = 8   // representative concrete invocations
const deepFailureModeCap = 12 // failure/recovery pairs
// Bounded evidence export: the first deepExcerptEpisodes anchors (corrected/
// failed first) carry a redacted transcript excerpt, each capped at
// deepExcerptLines / deepExcerptBytes, so the verifier sees real span text
// without an unbounded payload. This is a BOUNDED export, not the literal full text.
const deepExcerptEpisodes = 12
const deepExcerptLines = 60
const deepExcerptBytes = 1800

type deepFailureMode struct {
	Episode  string `json:"episode"`
	Failure  string `json:"failure"`
	Recovery string `json:"recovery,omitempty"`
}

type deepDossierRecord struct {
	SchemaVersion int    `json:"schema_version"`
	PatternID     string `json:"pattern_id"`
	ClusterKey    string `json:"cluster_key"`
	Fingerprint   string `json:"fingerprint"`
	// Archetype selects how the dossier renders into a SKILL.md: "procedure"
	// (a failure→recovery lesson from corrected episodes), "capability" (a
	// non-obvious convention/gotcha from durable facts), or "" for the legacy
	// command-sequence task dossier (now demoted to supporting evidence).
	Archetype        string            `json:"archetype,omitempty"`
	Title            string            `json:"title"`
	Trigger          string            `json:"trigger"`
	NotWhen          string            `json:"not_when,omitempty"`
	Knowledge        []string          `json:"knowledge,omitempty"`
	Preconditions    []string          `json:"preconditions"`
	Workflow         []string          `json:"workflow"`
	Variations       []string          `json:"variations"`
	Verification     []string          `json:"verification"`
	Parameters       []string          `json:"parameters"`
	FailureModes     []deepFailureMode `json:"failure_modes"`
	Facts            []string          `json:"facts"`
	SourceAnchors    []dossierAnchor   `json:"source_anchors"`
	Confidence       float64           `json:"confidence"`
	EvidenceEpisodes int               `json:"evidence_episodes"` // total in the full set
}

type deepEpisode struct {
	id, episodeKey, session, sourcePath, outcome string
	startLine, endLine                           int
}

// buildDeepDossier assembles the deep dossier for one pattern: the bounded but
// evidence-deep export over its complete backing-episode set, including redacted
// transcript excerpts for the top corrected/failed-first episodes.
func buildDeepDossier(db *sql.DB, brainDir, patternID string) (deepDossierRecord, error) {
	var (
		typ, cluster, title, intentSig, gram, metaID string
		strength                                     float64
	)
	err := db.QueryRow(`SELECT type, cluster_key, title, COALESCE(intent_sig,''), COALESCE(gram,''), COALESCE(meta_id,''), strength
		FROM patterns WHERE id=?`, patternID).Scan(&typ, &cluster, &title, &intentSig, &gram, &metaID, &strength)
	if err != nil {
		return deepDossierRecord{}, err
	}
	rec := deepDossierRecord{
		SchemaVersion: deepSchemaVersion,
		PatternID:     patternID,
		ClusterKey:    cluster,
		Title:         title,
		Trigger:       dossierTrigger(typ, intentSig, metaID),
		Confidence:    math.Round(strength*1000) / 1000,
		Preconditions: []string{},
		Workflow:      splitGramHeads(gram),
		Variations:    dossierVariants(db, typ, intentSig, gram),
		Verification:  []string{},
		Parameters:    []string{},
		FailureModes:  []deepFailureMode{},
		Facts:         []string{},
		SourceAnchors: []dossierAnchor{},
	}

	episodes, err := deepEvidenceEpisodes(db, typ, intentSig, gram, metaID)
	if err != nil {
		return rec, err
	}
	rec.EvidenceEpisodes = len(episodes)

	// Anchors: the full set, capped (already stratified corrected/failed first).
	// The first deepExcerptEpisodes carry a redacted transcript excerpt so the
	// verifier reasons over real span text, not just derived metadata.
	for i, e := range episodes {
		if i >= deepMaxEpisodes {
			break
		}
		a := dossierAnchor{
			SessionID: e.session, Transcript: redactText(e.sourcePath),
			StartLine: e.startLine, EndLine: e.endLine, Outcome: e.outcome,
		}
		if i < deepExcerptEpisodes {
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return stats, err
		}
		patternIDs = append(patternIDs, id)
	}
	rows.Close()

	ts := now.UTC().Format(time.RFC3339)
	for _, pid := range patternIDs {
		stats.Considered++
		deep, err := buildDeepDossier(db, brainDir, pid)
		if err != nil {
			stats.Failed++
			continue
		}
		var cachedFP, cachedVerdict string
		_ = db.QueryRow(`SELECT fingerprint, COALESCE(verdict,'') FROM deep_dossiers WHERE pattern_id=?`, pid).Scan(&cachedFP, &cachedVerdict)
		blob, err := json.Marshal(deep)
		if err != nil {
			stats.Failed++
			continue
		}
		jsonRedacted := redactText(string(blob))
		if cachedFP == deep.Fingerprint && cachedVerdict != "" {
			// Refresh the deterministic export but keep the cached verdict.
			if _, err := db.Exec(`UPDATE deep_dossiers SET json_redacted=?, status='current', updated_at=? WHERE pattern_id=?`,
				jsonRedacted, ts, pid); err != nil {
				return stats, err
			}
			stats.Cached++
			continue
		}
		verdict, raw, err := runDeepVerifier(ctx, repoDir, args, jsonRedacted, deep.Fingerprint, run)
		if err != nil {
			stats.Failed++
			continue
		}
		if _, err := db.Exec(`INSERT INTO deep_dossiers
			(pattern_id, fingerprint, json_redacted, verifier_json_redacted, verdict, status, created_at, updated_at)
			VALUES (?,?,?,?,?,'current',?,?)
			ON CONFLICT(pattern_id) DO UPDATE SET fingerprint=excluded.fingerprint, json_redacted=excluded.json_redacted,
			    verifier_json_redacted=excluded.verifier_json_redacted, verdict=excluded.verdict, status='current', updated_at=excluded.updated_at`,
			pid, deep.Fingerprint, jsonRedacted, redactText(raw), verdict.Verdict, ts, ts); err != nil {
			return stats, err
		}
		stats.Verified++
	}
	return stats, nil
}

func runDeepVerifier(ctx context.Context, repoDir string, args []string, deepJSON, fingerprint string, run distillAgentRunner) (dossierVerdict, string, error) {
	input := redactText(deepJSON)
	out, err := run(ctx, repoDir, args, []byte(input), dossierVerifyTimeout)
	if err != nil {
		return dossierVerdict{}, "", fmt.Errorf("deep verifier agent: %w", err)
	}
	v, raw, err := parseDossierVerdict(out)
	if err != nil {
		return dossierVerdict{}, "", err
	}
	v.EvidenceFingerprint = fingerprint
	return v, raw, nil
}

func runDossierVerifier(ctx context.Context, repoDir string, args []string, dossierJSON, fingerprint string, run distillAgentRunner) (dossierVerdict, string, error) {
	// Redaction boundary: the dossier is already redacted at rest, but redact
	// again defensively before it leaves the brain as agent input.
	input := redactText(dossierJSON)
	out, err := run(ctx, repoDir, args, []byte(input), dossierVerifyTimeout)
	if err != nil {
		return dossierVerdict{}, "", fmt.Errorf("verifier agent: %w", err)
	}
	v, raw, err := parseDossierVerdict(out)
	if err != nil {
		return dossierVerdict{}, "", err
	}
	// Pin the fingerprint to the evidence actually verified, regardless of what
	// the agent echoed back.
	v.EvidenceFingerprint = fingerprint
	return v, raw, nil
		return stats, err
	}
	wsBrainDir, err := workspaceDir(env, manifest.Name)
	if err != nil {
		return stats, err
	}
	err = withPatternCorpusMutationLocked(wsBrainDir, func(db *sql.DB) error {
		var mutationErr error
		stats, mutationErr = proposeWorkspaceFamiliesInDB(ctx, db, env, manifest, repoDir, agent, model, effort, run, now)
		return mutationErr
	})
	if err != nil {
		return stats, fmt.Errorf("workspace corpus not built (run `entire brain workspace patterns refresh %s`): %w", manifest.Name, err)
	}
	return stats, nil
}

func proposeWorkspaceFamiliesInDB(ctx context.Context, db *sql.DB, env EntireEnv, manifest workspaceManifest, repoDir, agent, model, effort string, run distillAgentRunner, now time.Time) (dossierVerifyStats, error) {
	var stats dossierVerifyStats
	// Gather each member's promotable task candidates (the cheap exact signal feeds
	// the agent, which merges across repos by meaning).
	perRepo := map[string][]map[string]any{}
	contributing := 0
	repos := append([]workspaceRepo(nil), manifest.Repos...)
	sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
	for _, repo := range repos {
		memberDir, err := brainDirForKey(env, repo.RepoKey)
		if err != nil {
			continue
		}
		cands, ok, err := loadCorpusTaskCandidatesChecked(memberDir)
		if err != nil {
			return stats, err
		}
		if !ok || len(cands) == 0 {
			continue
		}
		var list []map[string]any
		for i, c := range cands {
			if i >= workspaceFamilyMaxPerRepo {
				break
			}
			r := c.Reinforcement
			list = append(list, map[string]any{
				"intent": c.IntentSignature, "title": redactText(c.Label), "commands": redactStrings(c.Commands),
				"support": c.Support, "reinforcement": []int{r.Success, r.Corrected, r.Neutral},
			})
		}
		if len(list) > 0 {
			perRepo[repo.RepoKey] = list
			contributing++
		}
	}
	if contributing < workspaceMinRepos {
		return stats, nil // nothing can be cross-repo
	}

	// Fingerprint the actual evidence payload (per-repo intent + title + commands +
	// support + reinforcement), so changed member evidence invalidates the cached
	// families even when the set of repos/intents is unchanged.
	payload, _ := json.Marshal(map[string]any{"workspace": manifest.Name, "repos": perRepo})
	fp := proposalSampleFingerprint(payload)
	if corpusMeta(db, "workspace_families_fingerprint") == fp &&
		corpusScalar(db, `SELECT COUNT(*) FROM deep_dossiers WHERE pattern_id LIKE 'family:%'`) > 0 {
		stats.Cached = corpusScalar(db, `SELECT COUNT(*) FROM deep_dossiers WHERE pattern_id LIKE 'family:%'`)
		stats.Considered = stats.Cached
		return stats, nil
	}

	args, err := distillAgentCommandArgs(agent, nil, workspaceFamilyProposeSystemPrompt)
	if err != nil {
		return stats, err
	}
	args = injectAgentModel(args, agent, model)
	args = injectAgentEffort(args, agent, effort)
	out, err := run(ctx, repoDir, args, []byte(redactText(string(payload))), dossierVerifyTimeout)
	if err != nil {
		return stats, fmt.Errorf("workspace family proposal agent: %w", err)
	}
	families, err := parseWorkspaceFamilies(out)
	if err != nil {
		return stats, err
	}

	members := map[string]bool{}
	for k := range perRepo {
		members[k] = true
	}
	ts := now.UTC().Format(time.RFC3339)
	prepared := make([]workspaceFamily, 0, len(families))
	for _, f := range families {
		stats.Considered++
		// Curate per-repo variants to real members; require >=2 distinct repos.
		var variants []familyRepoVariant
		for _, v := range f.PerRepo {
			if members[v.RepoKey] {
				variants = append(variants, familyRepoVariant{RepoKey: v.RepoKey, Commands: redactStrings(v.Commands)})
			}
		}
		f.PerRepo = variants
		if f.repoCount() < workspaceMinRepos {
			stats.Failed++
			continue
		}
		f.Verdict = strings.ToLower(strings.TrimSpace(f.Verdict))
		if !allowedVerdicts[f.Verdict] {
			// A missing/unknown verdict must never be treated as accepted — it would
			// surface an unverified family. Default to the softest non-accepting verdict.
			f.Verdict = "low_confidence"
		}
		f.ID = "family:" + hexSHA(manifest.Name+"\x00"+f.Title+"\x00"+familyRepoKeysJoined(f))
		if !closed {
			_ = db.Close()
		}
	}()
	for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
		if _, err := db.Exec(p); err != nil {
			return err
		}
	}
	for _, stmt := range patternCorpusSchema {
		if _, err := db.Exec(stmt); err != nil {
			return fmt.Errorf("corpus schema: %w", err)
		}
	}

	// Indexer-version bump forces a full re-index (parser/extractor changed).
	if stored := corpusMeta(db, "pattern_indexer_version"); stored != strconv.Itoa(patternIndexerVersion) {
		if _, err := db.Exec(`DELETE FROM episodes`); err != nil { // cascades children
			return err
		}
		if _, err := db.Exec(`DELETE FROM indexed_sessions`); err != nil {
			return err
		}
	}

	repoKey := ""
	if manifest != nil {
		repoKey = manifest.RepoKey
	}
	var sessions []exportSession
	if manifest != nil && manifest.Sources != nil && manifest.Sources.Sessions != nil {
		sessions = manifest.Sources.Sessions.Sessions
	}
	// Session tombstones (Phase 4): excluded sessions and duplicate manifest
	// entries that alias an excluded transcript never enter the corpus; dropping
	// them from the present set prunes previously indexed rows below.
	sessions = guardExportSessions(guard, sessions)
	// Optional enrichment source: durable facts, branch-scoped. Missing is
	// empty, but corrupt/unsafe state fails closed and tombstoned-only facts are
	// filtered before they can be linked back into a rebuilt corpus.
	factsByBranch, err := loadAllFactBranchesForPrivacy(brainDir)
	if err != nil {
		return err
	}
	for branch, facts := range factsByBranch {
		factsByBranch[branch] = guardFactRecords(guard, facts)
	}

	present := map[string]bool{}
	for _, s := range sessions {
		rel := strings.TrimSpace(s.TranscriptPath)
		if rel == "" {
			continue
		}
		id := repoKey + "/" + filepath.ToSlash(rel)
		content, size, mtime, sha, readErr := readPatternCorpusTranscript(context.Background(), brainDir, filepath.ToSlash(rel))
		if readErr != nil {
			if errors.Is(readErr, os.ErrNotExist) {
				return &historySessionInventoryError{
					Path:   filepath.ToSlash(rel),
					Reason: "manifest-listed canonical transcript is missing; refusing a partial corpus publication",
					Err:    readErr,
				}
			}
			return readErr
		}
		present[id] = true
		if corpusSessionUnchanged(db, id, size, mtime, sha) {
			continue
		}
		if err := indexSessionIntoCorpus(db, repoKey, s, id, rel, content, size, mtime, sha, factsByBranch); err != nil {
			return err
		}
	}

	// Prune sessions no longer in the manifest (deleted transcripts).
	if err := pruneCorpusSessions(db, present); err != nil {
		return err
	}

	// Link episodes to semantic symbols (if a semantic index exists), then
	// rebuild candidate patterns, then materialize the synapse explanation graph.
	var sem *semanticSourceManifest
	if manifest.Sources != nil {
		sem = manifest.Sources.Semantic
	}
	if err := linkEpisodeSymbols(db, brainDir, sem); err != nil {
		return err
	}
	if err := buildPatternCandidates(db, repoKey, now); err != nil {
		return err
	}
	// Episode shapes (deterministic, token-free). Themes are NOT built here:
	// they are agent-proposed semantic clusters, created only by the explicit
	// `patterns verify --themes` (egress-gated) — refresh stays token-free.
	if err := classifyEpisodeShapes(db, now); err != nil {
		return err
	}
	if err := buildSynapses(db, now); err != nil {
		return err
	}
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	// Replace: delete this session's episodes (cascades children) + its row.
	if _, err := tx.Exec(`DELETE FROM episodes WHERE repo_key = ? AND session_id = ?`, repoKey, s.SessionID); err != nil {
		return err
	}
	if _, err := tx.Exec(`DELETE FROM indexed_sessions WHERE id = ?`, id); err != nil {
		return err
	}

	author := ""
	if len(s.Authors) > 0 {
		author = s.Authors[0].Name
	}
	createdAt := ""
	if !s.CreatedAt.IsZero() {
		createdAt = s.CreatedAt.UTC().Format(time.RFC3339)
	}

	episodeCount := 0
	for ord, seg := range segments {
		feedback := ""
		if ord+1 < len(segments) {
			feedback = segments[ord+1].Request.Text
		}
		committed := workCommitted(seg.WorkText)
		outcome, outcomeSource := corpusOutcome(feedback, committed)
		tools, commands, files := corpusEpisodeOps(seg.WorkText)
		exitFails := 0
		for _, c := range commands {
			if c.failed {
				exitFails++
			}
		}

		startLine := seg.Request.Line
		endLine := startLine
		if ord+1 < len(segments) && segments[ord+1].Request.Line > startLine {
			endLine = segments[ord+1].Request.Line - 1
		}

		epID := "episode:" + hexSHA(repoKey+"\x00"+filepath.ToSlash(rel)+"\x00"+strconv.Itoa(ord)+"\x00"+strconv.Itoa(startLine))
		epKey := repoKey + "/" + filepath.ToSlash(rel) + "#" + strconv.Itoa(ord)

		if _, err := tx.Exec(`INSERT INTO episodes
			(id, episode_key, repo_key, workspace, session_id, checkpoint_id, turn_id, turn_ord, branch, author_name, agent, created_at,
			 source_path, start_line, end_line, intent_raw, intent_sig, n_tools, tool_mix, files, n_cmds, exit_fails, outcome, outcome_source)
			VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
			epID, epKey, repoKey, "", s.SessionID, s.LatestCheckpoint, s.TurnID, ord, s.Branch, author, s.Agent, createdAt,
			filepath.ToSlash(rel), startLine, endLine, redactText(truncateString(seg.Request.Text, 280)), intentSignature(seg.Request.Text),
			len(tools), toolMix(tools), filesJSON(files), len(commands), exitFails, outcome, outcomeSource,
		); err != nil {
			return err
		}
		for i, t := range tools {
			if _, err := tx.Exec(`INSERT INTO episode_tools (episode_id, ord, tool_type, line) VALUES (?,?,?,?)`, epID, i, t.name, t.line); err != nil {
				return err
			}
		}
		for i, c := range commands {
			var exit any
			if c.exitCode != nil {
				exit = *c.exitCode
			}
			failed := 0
			if c.failed {
				failed = 1
			}
			if _, err := tx.Exec(`INSERT INTO episode_commands (episode_id, ord, head, raw_redacted, line, exit_code, failed) VALUES (?,?,?,?,?,?,?)`,
				epID, i, c.head, redactText(c.raw), c.line, exit, failed); err != nil {
				return err
			}
		}
		for _, f := range files {
			if _, err := tx.Exec(`INSERT OR IGNORE INTO episode_files (episode_id, path, action, line) VALUES (?,?,?,?)`,
				epID, redactText(f.path), f.action, f.line); err != nil {
				return err
			}
		}
		heads := make([]string, len(commands))
		for i, c := range commands {
