// buildWorkspacePatternCorpus rebuilds the workspace corpus from member corpora.
func buildWorkspacePatternCorpus(env EntireEnv, manifest workspaceManifest, now time.Time) (workspaceCorpusCounts, error) {
	if err := recoverWorkspacePatternCorpusPublication(env, manifest); err != nil {
		return workspaceCorpusCounts{}, err
	}
	policies, err := captureWorkspaceDerivedReadPolicies(env, manifest)
	if err != nil {
		return workspaceCorpusCounts{}, err
	}
	var counts workspaceCorpusCounts
	err = withLockedRetrievalPrivacyPolicies(policies, func() error {
		var buildErr error
		counts, buildErr = buildWorkspacePatternCorpusLocked(env, manifest, now)
		return buildErr
	})
	return counts, err
}

func buildWorkspacePatternCorpusLocked(env EntireEnv, manifest workspaceManifest, now time.Time) (workspaceCorpusCounts, error) {
	var counts workspaceCorpusCounts
	wsBrainDir, err := workspaceDir(env, manifest.Name)
	if err != nil {
		return counts, err
	}
	if err := recoverPatternCorpusPublicationLocked(wsBrainDir); err != nil {
		return counts, err
	}
	path, cleanup, err := preparePatternCorpusStaging(wsBrainDir)
	if err != nil {
		return counts, err
	}
	defer cleanup()
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		return counts, err
	}
	defer db.Close()
	for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
		if _, err := db.Exec(p); err != nil {
			return counts, err
		}
	}
	for _, stmt := range patternCorpusSchema {
		if _, err := db.Exec(stmt); err != nil {
			return counts, err
		}
	}

	repos := append([]workspaceRepo(nil), manifest.Repos...)
	sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
	counts.Members = len(repos)

	aggs := map[wsPatternKey]*wsAgg{}
	for _, repo := range repos {
		memberBrainDir, err := brainDirForKey(env, repo.RepoKey)
		if err != nil {
			counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
			continue
		}
		mdb, err := openPatternCorpusReadDB(memberBrainDir)
		if err != nil {
			if errors.Is(err, os.ErrNotExist) {
				// A genuinely absent member corpus degrades gracefully (refresh that repo).
				counts.Warnings = append(counts.Warnings, repo.RepoKey+": no corpus (run `entire brain refresh` there)")
				continue
			}
			return counts, err
		}
		counts.WithCorpus++
		if err := collectMemberPatterns(mdb.DB, repo.RepoKey, aggs); err != nil {
			counts.Warnings = append(counts.Warnings, repo.RepoKey+": "+err.Error())
		}
		mdb.Close()
	}

	tx, err := db.Begin()
	if err != nil {
		return counts, err
	}
	// Rebuildable: clear all prior workspace corpus content, including the
	// verifier-cache tables — they have no FK cascade, so stale verdicts must not
	// survive a rebuild and join onto a newly-rebuilt pattern row sharing the same
	// stable id (which could even suppress it as 'rejected').
	// themes has no FK to episodes (not cascaded) and is never populated at
	// workspace scope, so clear it too — a stray theme row must not persist
	// across rebuilds, be fetchable via `workspace get theme:…`, or skew run counts.
	// EXCEPTION: agent-verified workspace families (`family:%` deep_dossiers) are
	// NOT pattern rows (loadAcceptedWorkspaceFamilies reads them directly, never via
	// a pattern-id join), so the stale-join hazard above does not apply. They are an
	// expensive agent result keyed by their own member-evidence fingerprint, so a
	// deterministic rebuild preserves them; `workspace patterns verify` invalidates
	// and re-proposes them when that content fingerprint changes.
	for _, stmt := range []string{`DELETE FROM patterns`, `DELETE FROM episodes`, `DELETE FROM workspace_pattern_repos`, `DELETE FROM dossiers`, `DELETE FROM deep_dossiers WHERE pattern_id NOT LIKE 'family:%'`, `DELETE FROM themes`} {
		if _, err := tx.Exec(stmt); err != nil {
			tx.Rollback()
			return counts, err
		}
	}
