	memberCount := counts.Members
	for _, a := range aggs {
		if len(a.repos) < workspaceMinRepos {
			continue // a workspace pattern must be shared across ≥2 repos
		}
		if err := writeWorkspacePattern(tx, manifest.Name, a, memberCount, ts); err != nil {
			tx.Rollback()
			return counts, err
		}
