	}
	if err := tx.Commit(); err != nil {
		return counts, err
	}
	// Materialize the explanation graph (workspace_repo edges from the per-repo
	// breakdown) and record the run, mirroring the repo corpus build.
	if err := buildSynapses(db, now); err != nil {
		return counts, err
	}
