	if err != nil {
		return counts, err
	}
	if err := finalizePatternCorpusStagingLocked(wsBrainDir, path, db); err != nil {
		return counts, err
	}
	_ = appendPatternRun(wsBrainDir, run)
	return counts, nil
}

