	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			calls := 0
			watchTick(context.Background(), io.Discard, w, cursorPath, steps, &calls)
		}()
	}
	close(start)
