// Document transcripts use parser message anchors; JSONL uses physical lines.
func patternTranscriptEndLine(content string) int {
	if messages, ok := parseDocumentConversation(content); ok {
		last := 0
		for _, message := range messages {
			last = max(last, message.Line)
		}
		return last
	}
	content = strings.TrimRight(content, "\r\n")
	if content == "" {
		return 0
	}
	return strings.Count(content, "\n") + 1
}

