		SELECT id, type, cluster_key, title, intent_sig, gram, meta_id, strength,
		       outcome_corrected, outcome_failed
		FROM patterns
		WHERE repo_key=? AND strength >= ?
		ORDER BY strength DESC`, repoKey, promotionThreshold)
	if err != nil {
		return err
	}
	defer rows.Close()
	type promotable struct {
