		if err := rows.Scan(&p.id, &p.typ, &p.cluster, &p.title, &p.intentSig, &p.gram, &p.metaID, &p.strength, &p.corrected, &p.failed); err != nil {
			return err
		}
		ps = append(ps, p)
	}
