package cli

import (
	"os"
	"path/filepath"
	"testing"
)

func TestSkillReplacementPreservesHardlinkAlias(t *testing.T) {
	d := t.TempDir()
	dest, err := skillDestinations("standard", "repo", "audit", d)
	if err != nil {
		t.Fatal(err)
	}
	outside := filepath.Join(t.TempDir(), "outside")
	os.WriteFile(outside, []byte("original"), 0600)
	os.MkdirAll(filepath.Dir(dest[0].Path), 0700)
	if err := os.Link(outside, dest[0].Path); err != nil {
		t.Skip(err)
	}
	if err := writeSkillFile(dest[0], []byte("replacement skill")); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(outside)
	if err != nil || string(got) != "original" {
		t.Fatalf("regression %q %v", got, err)
	}
	t.Log("outside hard-linked file unchanged")
}

func TestSkillReplacementRejectsSwappedDirectory(t *testing.T) {
	base := t.TempDir()
	dests, err := skillDestinations("standard", "repo", "swap", base)
	if err != nil {
		t.Fatal(err)
	}
	d := dests[0]
	parent := filepath.Dir(d.Path)
	if err := os.MkdirAll(parent, 0700); err != nil {
		t.Fatal(err)
	}
	outside := t.TempDir()
	sentinel := filepath.Join(outside, "SKILL.md")
	if err := os.WriteFile(sentinel, []byte("outside"), 0600); err != nil {
		t.Fatal(err)
	}
	err = writeSkillFileBeforeReplace(d, []byte("replacement"), func() {
		if err := os.Rename(parent, parent+"-moved"); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink(outside, parent); err != nil {
			t.Fatal(err)
		}
	})
	if err == nil {
		t.Fatal("directory swap accepted")
	}
	got, readErr := os.ReadFile(sentinel)
	if readErr != nil || string(got) != "outside" {
		t.Fatalf("outside changed: %q %v", got, readErr)
	}
	entries, err := os.ReadDir(parent + "-moved")
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 0 {
		t.Fatalf("temporary files leaked: %v", entries)
	}
}
	return writeSkillFileBeforeReplace(d, data, nil)
}

// beforeReplace is a deterministic directory-swap test seam; production passes nil.
func writeSkillFileBeforeReplace(d skillDestination, data []byte, beforeReplace func()) error {
	base := skillFilePath(d.base)
	rel := filepath.FromSlash(d.rel)
	if err := rejectSymlinkedBrainRoot(base); err != nil {
		return fmt.Errorf("refusing to write skill to %s: %w", d.Path, err)
	}
	if err := rejectExistingSymlinkPathComponents(base, rel); err != nil {
		return fmt.Errorf("refusing to write skill to %s: %w", d.Path, err)
	}
	abs := filepath.Join(base, rel)
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return fmt.Errorf("create skill dir: %w", err)
	}
	// Re-check after MkdirAll: the directories that did not exist a moment ago
	// do now, and creating them must not have traversed a link.
	if err := rejectSymlinkedBrainRoot(base); err != nil {
		return fmt.Errorf("refusing to write skill to %s: %w", d.Path, err)
	}
	if err := rejectExistingSymlinkPathComponents(base, rel); err != nil {
		return fmt.Errorf("refusing to write skill to %s: %w", d.Path, err)
	}
	parent := filepath.Dir(abs)
	expected, err := os.Lstat(parent)
	if err != nil {
		return err
	}
	root, err := os.OpenRoot(parent)
	if err != nil {
		return err
	}
	defer root.Close()
	opened, err := root.Stat(".")
	if err != nil {
		return err
	}
	if !os.SameFile(expected, opened) {
		return fmt.Errorf("skill destination directory changed")
	}
	// A fresh inode replaces the named leaf, leaving any hard-linked aliases intact.
	name := ".skill-" + rand.Text() + ".tmp"
	tmp, err := root.OpenFile(name, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	defer root.Remove(name)
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if beforeReplace != nil {
		beforeReplace()
	}
	if err := rejectSymlinkedBrainRoot(base); err != nil {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(base, rel); err != nil {
		return err
	}
	current, err := os.Lstat(parent)
	if err != nil {
		return err
	}
	if !os.SameFile(expected, current) {
		return fmt.Errorf("skill destination directory changed")
	}
	if err := root.Rename(name, filepath.Base(abs)); err != nil {
		return fmt.Errorf("write skill: %w", err)
	}
	return nil
}

